INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.d', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM', 'd', 'kuchangamkia matumizi ya usemi halisi na usemi wa taarifa katika mawasiliano', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU', 'kiswahili', 8, 'Sikiliza na ujibu mahojiano ipasavyo', ARRAY['KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.a', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.b', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.c']::text[], 'Names the features to keep in this kind of talk (mahojiano), picks the better of two ways to listen or reply in a situation on usafi wa soko la mji, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Dondoa habari mahususi katika kifungu cha simulizi', ARRAY['KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Panga matukio yanavyofuatana katika kifungu', ARRAY['KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Fanya utabiri na ufasiri kutokana na kifungu', ARRAY['KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Eleza maana ya msamiati katika kifungu', ARRAY['KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.d']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA', 'KISW.G8.KUANDI.T1_VIAKIFISHI', 'kiswahili', 8, 'Tumia alama ya hisi na ritifaa', ARRAY['KISW.G8.KUANDI.T1_VIAKIFISHI.a', 'KISW.G8.KUANDI.T1_VIAKIFISHI.b']::text[], 'Mtoto hutumia alama ya hisi (!) mwishoni mwa sentensi ya mshangao au amri kali, na ritifaa ('') katika maneno kama ng''ombe na ng''ambo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI', 'KISW.G8.SARUFI.T1_VIWAKILISHI', 'kiswahili', 8, 'Tambua viwakilishi vya nafsi, vionyeshi na vya idadi', ARRAY['KISW.G8.SARUFI.T1_VIWAKILISHI.a', 'KISW.G8.SARUFI.T1_VIWAKILISHI.b']::text[], 'Mtoto hutambua viwakilishi vya nafsi (mimi, wewe, yeye, sisi, ninyi, wao), vionyeshi (huyu, huyo, yule) na vya idadi (wawili, watatu), na huvitumia badala ya nomino. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA', 'kiswahili', 8, 'Tofautisha sauti /gh/ na /g/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.a', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.b', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.c']::text[], 'Hears, says and writes the right sound in syllables and words with /gh/ na /g/ (ghali and gali, lugha and luga), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA', 'kiswahili', 8, 'Eleza ujumbe wa matini aliyosoma', ARRAY['KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.a', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.b', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI', 'kiswahili', 8, 'Tambua muundo na umuhimu wa barua ya kirafiki ya shukrani', ARRAY['KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.a', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.b']::text[], 'Mtoto hueleza kuwa barua ya shukrani huonyesha kuthamini wema na hutambua vipengele vyake (anwani, tarehe, salamu, ujumbe, hitimisho, jina). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI', 'kiswahili', 8, 'Andika barua ya kirafiki ya kutoa shukrani', ARRAY['KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.c']::text[], 'Tells barua ya kirafiki from other kinds of writing and its parts, and writes a friendly letter with the address, date, greeting, asking after the friend, the news, and a friendly closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI', 'KISW.G8.SARUFI.T2_VIWAKILISHI', 'kiswahili', 8, 'Tambua viwakilishi viulizi na vya sifa', ARRAY['KISW.G8.SARUFI.T2_VIWAKILISHI.a', 'KISW.G8.SARUFI.T2_VIWAKILISHI.b']::text[], 'Mtoto hutambua viwakilishi viulizi (nani, nini, lipi, kipi, ngapi) vinavyouliza, na vya sifa vinavyochukua nafasi ya nomino na sifa yake (mrefu amefika). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T3_HADITHI.MIGHANI', 'KISW.G8.KUSIKI.T3_HADITHI', 'kiswahili', 8, 'Eleza maana, aina na sifa za hadithi', ARRAY['KISW.G8.KUSIKI.T3_HADITHI.a', 'KISW.G8.KUSIKI.T3_HADITHI.b', 'KISW.G8.KUSIKI.T3_HADITHI.c', 'KISW.G8.KUSIKI.T3_HADITHI.d']::text[], 'Explains the maana of hadithi (mighani, visasili) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA', 'kiswahili', 8, 'Eleza maana na sifa za tamthilia', ARRAY['KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.a', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.b']::text[], 'Explains the utanzu of a tamthilia read in class ("Kilio cha Msitu") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Bainisha wazo kuu na uandike insha ya masimulizi inayoliendeleza', ARRAY['KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.b']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI', 'KISW.G8.SARUFI.T3_VIWAKILISHI', 'kiswahili', 8, 'Tambua viwakilishi vimilikishi na visisitizi', ARRAY['KISW.G8.SARUFI.T3_VIWAKILISHI.a', 'KISW.G8.SARUFI.T3_VIWAKILISHI.b']::text[], 'Mtoto hutambua kimilikishi (changu, chake, chetu, vyao) kinachoonyesha umiliki na kisisitizi (mwenyewe, wenyewe) kinachosisitiza mtu au kitu. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T4_HADITHI.VISASILI', 'KISW.G8.KUSIKI.T4_HADITHI', 'kiswahili', 8, 'Wasilisha hadithi kwa kuzingatia vipengele vya uwasilishaji', ARRAY['KISW.G8.KUSIKI.T4_HADITHI.a', 'KISW.G8.KUSIKI.T4_HADITHI.b', 'KISW.G8.KUSIKI.T4_HADITHI.c']::text[], 'Explains the uwasilishaji of hadithi (visasili, mighani) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA', 'kiswahili', 8, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.a', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.b', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.c', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.d', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Andika insha ya masimulizi kwa mbinu za lugha, wahusika na mandhari', ARRAY['KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.b', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.c', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.d']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI', 'kiswahili', 8, 'Tambua hali ya mazoea na hali timilifu', ARRAY['KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.a', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.b', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.c']::text[], 'Mtoto hutambua hali ya mazoea inayotumia hu- (huenda sokoni kila siku) na hali timilifu inayotumia -me- (amefika) kuonyesha tendo lililokamilika. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO', 'kiswahili', 8, 'Tambua maagizo na sifa zake katika matini ya kusikiliza', ARRAY['KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.b', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.c', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.a', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.d']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Dondoa habari na eleza msamiati kulingana na muktadha', ARRAY['KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO', 'kiswahili', 8, 'Tambua na andika insha ya maelekezo', ARRAY['KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.a', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.b', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.c']::text[], 'Tells insha ya maelekezo from other kinds of writing and its parts, and writes instructions with their purpose, the materials, the steps in order as commands, and safety warnings; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI', 'kiswahili', 8, 'Tambua uliopita timilifu na ujao timilifu', ARRAY['KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.a', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.b', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.c']::text[], 'Mtoto hutambua uliopita timilifu (alikuwa amefika) na ujao timilifu (atakuwa amefika), na hutofautisha kila mmoja na wakati rahisi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS', 'kiswahili', 8, 'Tambua ujumbe na mafunzo katika matini ya kusikiliza', ARRAY['KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.a', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.b', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.c']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT', 'kiswahili', 8, 'Jadili maudhui na dhamira katika tamthilia', ARRAY['KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.a', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.b', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.c']::text[], 'Explains the maudhui of a tamthilia read in class ("Kilio cha Msitu") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Andika insha ya mdokezo', ARRAY['KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.b', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.c', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.d']::text[], 'Tells insha ya mdokezo from other kinds of writing and its parts, and writes a story that starts or ends with the exact words given and leads to them; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA', 'KISW.G8.SARUFI.T6_VIVUMISHI', 'kiswahili', 8, 'Tambua vivumishi vya sifa na vya kuashiria', ARRAY['KISW.G8.SARUFI.T6_VIVUMISHI.a', 'KISW.G8.SARUFI.T6_VIVUMISHI.b']::text[], 'Mtoto hutambua kivumishi cha sifa (mzuri, refu) kinachoeleza nomino na kivumishi cha kuashiria (huyu, huo, ile) kinachoonyesha nomino. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI', 'kiswahili', 8, 'Tumia usikilizaji husishi katika mazungumzo', ARRAY['KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.a', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.b', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.c']::text[], 'Names the features to keep in this kind of talk (husishi), picks the better of two ways to listen or reply in a situation on kumsaidia mwanafunzi mwenye ulemavu, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T7_.KUFUPISHA', 'KISW.G8.KUSOMA.T7_', 'kiswahili', 8, 'Fupisha kifungu kwa kuzingatia vipengele vya ufupisho', ARRAY['KISW.G8.KUSOMA.T7_.a', 'KISW.G8.KUSOMA.T7_.b', 'KISW.G8.KUSOMA.T7_.c']::text[], 'Explains what a summary is, picks the main points of a passage on the theme (not the examples), and writes them in his own words, in order, within the word limit and without his own opinion; written summaries are marked by the teacher, and in the app the child picks the right point in 8 of 10 new items.', '["chagua hoja kuu","tambua kisichofaa katika ufupisho","andika ufupisho (mwalimu anasahihisha)"]'::jsonb, '["analysis","synthesis"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Tumia tamathali za lugha kujenga picha dhahiri katika insha ya maelezo', ARRAY['KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.b', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI', 'KISW.G8.SARUFI.T7_VIVUMISHI', 'kiswahili', 8, 'Tambua vivumishi vimilikishi na vya idadi', ARRAY['KISW.G8.SARUFI.T7_VIVUMISHI.a', 'KISW.G8.SARUFI.T7_VIVUMISHI.b']::text[], 'Mtoto hutambua kivumishi kimilikishi (kitabu changu, nyumba yake) na cha idadi (watoto wawili, vitabu vitatu) kinachofuata nomino. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_', 'kiswahili', 8, 'Zungumza papo kwa hapo kwa mpangilio', ARRAY['KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.a', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.b', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.c']::text[], 'Names the features to keep in this kind of talk (papo), picks the better of two ways to listen or reply in a situation on jinsi ya kujikinga na wezi wa mtandaoni, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT', 'kiswahili', 8, 'Eleza mandhari na ploti ya tamthilia', ARRAY['KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.a', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.b', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.c']::text[], 'Explains the mandhari of a tamthilia read in class ("Kilio cha Msitu") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI', 'KISW.G8.KUANDI.T8_VIAKIFISHI', 'kiswahili', 8, 'Tumia alama za mtajo na mshazari', ARRAY['KISW.G8.KUANDI.T8_VIAKIFISHI.a', 'KISW.G8.KUANDI.T8_VIAKIFISHI.b']::text[], 'Mtoto hutumia alama za mtajo (" ") kunukuu maneno halisi ya mtu au kichwa cha kitabu, na mshazari (/) kutenga machaguo au kuandika tarehe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_', 'kiswahili', 8, 'Tumia ngeli ya I-ZI na upatanisho wa kisarufi', ARRAY['KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.a', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.b', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua nomino za I-ZI (nyumba, meza, ndege, barua) na hutumia viambishi i- (umoja) na zi- (wingi): nyumba inapendeza, nyumba zinapendeza. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA', 'kiswahili', 8, 'Tofautisha sauti /ch/ na /sh/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.a', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.b', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.c']::text[], 'Hears, says and writes the right sound in syllables and words with /ch/ na /sh/ (chaka and shaka, chali and shali), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Soma kifungu cha kushawishi: habari, utabiri, msamiati na ushawishi', ARRAY['KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.c', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.d']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Andika insha ya masimulizi ukikuza wazo katika kila aya', ARRAY['KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.b', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_', 'kiswahili', 8, 'Tumia ngeli za U-U na U-YA na upatanisho wa kisarufi', ARRAY['KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.a', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.b', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua nomino za U-U (uji, ugali, unga, upendo) zinazotumia u-: uji umeiva, na za U-YA (ugonjwa, magonjwa) zinazotumia u- na ya-: ugonjwa unaumiza, magonjwa yanaumiza. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA', 'KISW.G8.KUSIKI.T10_HADITHI', 'kiswahili', 8, 'Eleza maana, aina na sifa za hadithi', ARRAY['KISW.G8.KUSIKI.T10_HADITHI.a', 'KISW.G8.KUSIKI.T10_HADITHI.b', 'KISW.G8.KUSIKI.T10_HADITHI.c', 'KISW.G8.KUSIKI.T10_HADITHI.d']::text[], 'Explains the maana of hadithi (hurafa, hekaya) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA', 'kiswahili', 8, 'Chambua wahusika na sifa zao katika tamthilia', ARRAY['KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.a', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.b', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.c']::text[], 'Explains the wahusika of a tamthilia read in class ("Kilio cha Msitu") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 8, 'Tambua muundo wa barua rasmi ya kuomba msaada', ARRAY['KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.a', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.b']::text[], 'Mtoto hutambua vipengele vya barua rasmi (anwani mbili, tarehe, salamu rasmi, kichwa, ujumbe, hitimisho) na kuwa lugha yake ni ya heshima. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 8, 'Andika barua rasmi ya kuomba msaada', ARRAY['KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.c']::text[], 'Tells barua rasmi from other kinds of writing and its parts, and writes an official letter with two addresses, the date, a formal greeting, a KUH: line, the message and Wako mtiifu with a signature; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_', 'kiswahili', 8, 'Tambua vinyume vya vitenzi na vielezi', ARRAY['KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.a', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.b', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.c']::text[], 'Mtoto hueleza kinyume ni neno lenye maana kinyume na hutambua vinyume vya vitenzi (fungua na funga, nunua na uza) na vya vielezi (juu na chini, mbele na nyuma, polepole na haraka). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM', 'kiswahili', 8, 'Zungumza kwa kutumia vidokezo vya hoja', ARRAY['KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.a', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.b', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.c', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.d']::text[], 'Names the features to keep in this kind of talk (vidokezo), picks the better of two ways to listen or reply in a situation on haki ya mtoto kupata elimu, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA', 'kiswahili', 8, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.a', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.b', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.c']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Andika insha ya maelezo kwa kuzingatia vipengele vyake', ARRAY['KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN', 'kiswahili', 8, 'Tambua kauli za kutendeka, kutendewa na kutendatenda', ARRAY['KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.a', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.b']::text[], 'Mtoto hutambua kutendeka (pika, pikika), kutendewa (pikiwa) na kutendatenda (pigapiga, tendo linalorudiwa). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN', 'kiswahili', 8, 'Eleza habari, dondoa mpangilio na msamiati katika matini ya kusikiliza', ARRAY['KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.a', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.b', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.c']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA', 'kiswahili', 8, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.a', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.b', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.c', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.d', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU', 'kiswahili', 8, 'Tambua na andika hotuba ya kutoa ufafanuzi', ARRAY['KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.a', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.b', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.c', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.d']::text[], 'Tells hotuba from other kinds of writing and its parts, and writes a speech with the itifaki, words spoken to the audience, facts the listener can use and a closing with thanks; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI', 'kiswahili', 8, 'Tambua sentensi changamano', ARRAY['KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.a', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.b', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.c']::text[], 'Mtoto hueleza sentensi changamano ina kishazi huru (kinachojitegemea) na kishazi tegemezi (kisichojitegemea), kama "Mtoto aliyeshinda alipewa zawadi". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI', 'KISW.G8.KUSIKI.T13_HADITHI', 'kiswahili', 8, 'Chambua wahusika katika hadithi', ARRAY['KISW.G8.KUSIKI.T13_HADITHI.a', 'KISW.G8.KUSIKI.T13_HADITHI.b', 'KISW.G8.KUSIKI.T13_HADITHI.c']::text[], 'Explains the wahusika of hadithi (hurafa, ngano) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT', 'kiswahili', 8, 'Tambua mbinu za lugha na umuhimu wake katika tamthilia', ARRAY['KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.a', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.b']::text[], 'Explains the mbinu of a tamthilia read in class ("Kilio cha Msitu") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI', 'kiswahili', 8, 'Andika insha ya maelezo inayodhihirisha sifa za mahali', ARRAY['KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.a', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.b', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN', 'kiswahili', 8, 'Kanusha sentensi katika hali ya mazoea na timilifu', ARRAY['KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.b', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.c', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.a']::text[], 'Mtoto hukanusha hali timilifu kwa ha-ja- (amefika, hajafika) na hali ya mazoea kwa kuondoa hu- (hufika, hafiki). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI', 'KISW.G8.KUSIKI.T14_HADITHI', 'kiswahili', 8, 'Tambua vipengele vya lugha katika hadithi', ARRAY['KISW.G8.KUSIKI.T14_HADITHI.a', 'KISW.G8.KUSIKI.T14_HADITHI.b', 'KISW.G8.KUSIKI.T14_HADITHI.c']::text[], 'Explains the lugha of hadithi (hurafa, ngano) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU', 'kiswahili', 8, 'Soma kifungu cha mjadala: habari, msamiati na mitazamo', ARRAY['KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.a', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.b', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO', 'kiswahili', 8, 'Tambua na andika insha ya maelekezo', ARRAY['KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.a', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.b']::text[], 'Tells insha ya maelekezo from other kinds of writing and its parts, and writes instructions with their purpose, the materials, the steps in order as commands, and safety warnings; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO', 'kiswahili', 8, 'Tambua nomino katika hali ya udogo', ARRAY['KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.a', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.b', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.c']::text[], 'Mtoto hutambua kijiji (mji mdogo), kijiti (mti mdogo), kijumba (nyumba ndogo) na kitoto (mtoto mdogo), na kuwa ki- na kiambishi chake huonyesha udogo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI', 'kiswahili', 8, 'Tumia usikilizaji husishi katika mazungumzo', ARRAY['KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.a', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.b', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.c', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.d']::text[], 'Names the features to keep in this kind of talk (husishi), picks the better of two ways to listen or reply in a situation on rafiki aliyekosewa na wenzake, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO', 'KISW.G8.KUSOMA.T15_UFUPISHO', 'kiswahili', 8, 'Eleza ufupisho na habari kuu ya aya', ARRAY['KISW.G8.KUSOMA.T15_UFUPISHO.a', 'KISW.G8.KUSOMA.T15_UFUPISHO.b']::text[], 'Mtoto hueleza ufupisho ni kutoa habari kuu bila kupoteza maana na hutambua habari kuu ya aya. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'KISW.G8.KUSOMA.T15_UFUPISHO', 'kiswahili', 8, 'Eleza ujumbe wa aya na wa matini kwa ufupi', ARRAY['KISW.G8.KUSOMA.T15_UFUPISHO.a', 'KISW.G8.KUSOMA.T15_UFUPISHO.b', 'KISW.G8.KUSOMA.T15_UFUPISHO.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI', 'kiswahili', 8, 'Tambua vipengele vya baruapepe ya kiofisi', ARRAY['KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.a', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.b']::text[], 'Mtoto hutambua anwani ya mpokeaji, kichwa cha habari (mada), salamu, ujumbe, hitimisho na jina la mwandishi, na kuwa lugha ni rasmi na fupi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI', 'kiswahili', 8, 'Andika baruapepe ya kiofisi kwa lugha na muundo ufaao', ARRAY['KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.c', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.d']::text[], 'Tells baruapepe from other kinds of writing and its parts, and writes an email with the receiver''s address, a short subject, a greeting, the message in correct Kiswahili and a closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM', 'kiswahili', 8, 'Tambua usemi halisi na wa taarifa', ARRAY['KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.a', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.c', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.b']::text[], 'Mtoto hutambua usemi halisi (maneno kamili ndani ya alama za usemi) na wa taarifa (bila alama za usemi, kwa kutumia kwamba au kuwa), na hubadilisha mtu ipasavyo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
