INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO.M8_ORL_CLOSEDQ_T1', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO', 'Asks only yes/no questions in an interview.', '{"question":"Ni swali lipi bora la mahojiano?","wrong_answer":"Unapenda kazi yako?","correct_answer":"Kazi yako ya kusafisha mji ina changamoto zipi?"}'::jsonb, 'Yes/no questions are the easiest to make.', 'The question "Ni swali lipi bora la mahojiano?" with "Unapenda kazi yako?" among the options.', 'Turn each yes/no question into a "nini, vipi, kwa nini" question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO.M8_ORL_NOINTRO_T1', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO', 'Starts the interview without greeting and introducing himself and the purpose.', '{"question":"Mahojiano huanza vipi?","wrong_answer":"swali la kwanza moja kwa moja","correct_answer":"salamu, kujitambulisha na kueleza lengo"}'::jsonb, 'The child goes straight to the questions.', 'The question "Mahojiano huanza vipi?" with "swali la kwanza moja kwa moja" among the options.', 'Script the opening together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO.M8_ORL_INTERRUPT_T1', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO.M8_ORL_SLANG_T1', 'KISW.G8.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAHOJIANO', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS8_RS_HABARI_DETAIL', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS8_RS_HABARI_OPPOSITE', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
