INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI.M_KS8_RS_MSAMIATI_NOTSAID', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M8_HAB_RS_HABARI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Answers a "why" question with a "what" (an event, not its reason).', '{"question":"Kwa nini mhusika alikimbia nyumbani?","wrong_answer":"alikimbia nyumbani","correct_answer":"kwa sababu aliogopa mbwa wa jirani"}'::jsonb, 'The child finds the sentence with the words of the question and copies the event.', 'The question "Kwa nini mhusika alikimbia nyumbani?" with "alikimbia nyumbani" among the options.', 'Underline the question word: nini, nani, wapi, lini, kwa nini; the answer must fit it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO.M8_MAT_RS_MATUKIO', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'Orders the events as they are told in the question or the options, not as they happen in the passage.', '{"question":"Ni tukio lipi lilitokea kwanza katika kifungu?","wrong_answer":"tukio lililotajwa kwanza katika swali","correct_answer":"tukio la kwanza katika kifungu"}'::jsonb, 'The order of the options is taken for the order of the story.', 'The question "Ni tukio lipi lilitokea kwanza katika kifungu?" with "tukio lililotajwa kwanza katika swali" among the options.', 'Number the events in the margin of the passage before looking at the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI.M8_UTB_RS_UTABIRI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'Predicts with no clue from the passage, from what he wishes would happen.', '{"question":"Kutokana na kifungu, nini kitatokea baadaye?","wrong_answer":"mhusika atakuwa tajiri sana","correct_answer":"jibu linalotokana na vidokezo vya kifungu"}'::jsonb, 'Prediction is taken as imagination.', 'The question "Kutokana na kifungu, nini kitatokea baadaye?" with "mhusika atakuwa tajiri sana" among the options.', 'Every prediction needs a clue: "kwa sababu kifungu kinasema..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI.M8_MSM_RS_MSAMIATI', 'KISW.G8.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'Gives the meaning of a look-alike word, or the everyday meaning where the passage means another.', '{"question":"Katika kifungu, neno \"kupiga\" katika \"alipiga simu\" lina maana gani?","wrong_answer":"kumpiga mtu","correct_answer":"kuwasiliana kwa simu"}'::jsonb, 'The child knows one meaning and does not test it against the sentence.', 'The question "Katika kifungu, neno "kupiga" katika "alipiga simu" lina maana gani?" with "kumpiga mtu" among the options.', 'Put each meaning into the sentence; keep the one that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA.M_KS8_HR_HISI', 'KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA', 'Ends an exclamation with a full stop.', '{"question":"Sentensi ya mshangao huisha kwa nini?","wrong_answer":"kikomo","correct_answer":"alama ya hisi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kikomo" next to the right answer and ask the question again in a new sentence.', 'Sentensi ya mshangao huisha kwa alama ya hisi (!).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA.M_KS8_HR_RITIFAA', 'KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA', 'Writes ng''ombe without the apostrophe.', '{"question":"Ni neno lipi limeandikwa sawa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ngombe" next to the right answer and ask the question again in a new sentence.', 'Ng''ombe huandikwa kwa ritifaa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA.M_KS8_HR_AMRI', 'KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA', 'Ends a strong command with a question mark.', '{"question":"Amri kali huisha kwa nini?","wrong_answer":"kiulizi","correct_answer":"alama ya hisi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kiulizi" next to the right answer and ask the question again in a new sentence.', 'Amri kali huisha kwa alama ya hisi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA.M8_HR_DOUBLE', 'KISW.G8.KUANDI.T1_VIAKIFISHI.HISI_RITIFAA', 'Uses many marks together for strong feeling (Lo!!! or Kweli?!?).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Lo!!! Umeshinda!!!","correct_answer":"Lo! Umeshinda!"}'::jsonb, 'Chat messages use many marks to show strength of feeling.', 'The question "Ni ipi imeandikwa sawa?" with "Lo!!! Umeshinda!!!" among the options.', 'One alama ya hisi is enough in standard writing; the words carry the strength.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI.M_KS8_VN_NAFSI', 'KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI', 'Mixes person pronouns.', '{"question":"Ni kiwakilishi kipi cha nafsi ya kwanza wingi?","wrong_answer":"wao","correct_answer":"sisi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wao" next to the right answer and ask the question again in a new sentence.', 'Sisi ni nafsi ya kwanza wingi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI.M_KS8_VN_ONYESHI', 'KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI', 'Mixes demonstratives.', '{"question":"Ni kiwakilishi kipi cha kuonyesha mtu aliye karibu?","wrong_answer":"yule","correct_answer":"huyu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "yule" next to the right answer and ask the question again in a new sentence.', 'Huyu huonyesha aliye karibu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI.M_KS8_VN_IDADI', 'KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI', 'Does not know number pronouns.', '{"question":"Ni kiwakilishi kipi cha idadi?","wrong_answer":"huyu","correct_answer":"wawili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "huyu" next to the right answer and ask the question again in a new sentence.', 'Wawili ni kiwakilishi cha idadi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI.M8_VN_IDADI_ADJ', 'KISW.G8.SARUFI.T1_VIWAKILISHI.VIW_NAFSI', 'Takes a number after a noun (watoto wawili) for a number pronoun, which stands alone (Wawili walifika).', '{"question":"Katika \"Wawili walifika mapema\", \"Wawili\" ni nini?","wrong_answer":"kivumishi cha idadi","correct_answer":"kiwakilishi cha idadi"}'::jsonb, 'The same word is an adjective when it follows a noun and a pronoun when it stands for it.', 'The question "Katika "Wawili walifika mapema", "Wawili" ni nini?" with "kivumishi cha idadi" among the options.', 'Ask: is there a noun before it? If not, it stands for the noun: a pronoun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SWAP_T2', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /g/ for /gh/, so ghali (expensive) becomes gali (not a Kiswahili word (a spelling error)).', '{"question":"Mwalimu anasema: \"ghali\". Umesikia neno lipi?","wrong_answer":"gali","correct_answer":"ghali"}'::jsonb, '/gh/ is made further back in the throat than /g/ and comes into Kiswahili from Arabic; most Kenyan first languages have no /gh/, so the child says and writes g.', 'The question "Mwalimu anasema: "ghali". Umesikia neno lipi?" with "gali" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SPELL_T2', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (luga where lugha is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"a language\".","wrong_answer":"luga","correct_answer":"lugha"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "a language"." with "luga" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SAME_T2', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"lugha\" na \"luga\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""lugha" na "luga" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_TWISTER_T2', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Meza dawa kwa kufuata maagizo ya daktari.","correct_answer":"Ghafla Ghalib aligharimika gharama ghali ya dawa ya ghala."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Meza dawa kwa kufuata maagizo ya daktari." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SYLL_T2', 'KISW.G8.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Breaks the word into syllables at the wrong place, so the target sound is lost (gh-ali read as two wrong parts).', '{"question":"Neno \"ghali\" lina silabi zipi?","wrong_answer":"g-hali","correct_answer":"gha-li"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "ghali" lina silabi zipi?" with "g-hali" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS8_RS_UJUMBE_DETAIL', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS8_RS_UJUMBE_OPPOSITE', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS8_RS_UJUMBE_NOTSAID', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M8_UJM_RS_UJUMBE', 'KISW.G8.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Gives a detail of the chosen text as its message.', '{"question":"Ujumbe wa matini uliyochagua ni upi?","wrong_answer":"jambo moja dogo lililotokea","correct_answer":"funzo kuu la matini yote"}'::jsonb, 'The detail is vivid.', 'The question "Ujumbe wa matini uliyochagua ni upi?" with "jambo moja dogo lililotokea" among the options.', 'Ask what the whole text teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI.M_KS8_BH_MAANA', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI', 'Thinks a thanks letter asks for something.', '{"question":"Barua ya shukrani huandikwa kwa nini?","wrong_answer":"kuomba kitu","correct_answer":"kuthamini wema"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kuomba kitu" next to the right answer and ask the question again in a new sentence.', 'Barua ya shukrani huthamini wema.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI.M_KS8_BH_SALAMU', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI', 'Uses a formal greeting.', '{"question":"Ni salamu ipi inafaa barua ya shukrani ya kirafiki?","wrong_answer":"Mkuu wa Shule","correct_answer":"Mpendwa rafiki yangu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mkuu wa Shule" next to the right answer and ask the question again in a new sentence.', 'Barua ya kirafiki hutumia salamu ya kirafiki.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI.M_KS8_BH_MWANZO', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI', 'Starts with the closing.', '{"question":"Barua huanza kwa nini?","wrong_answer":"jina la mwandishi","correct_answer":"anwani na tarehe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jina la mwandishi" next to the right answer and ask the question again in a new sentence.', 'Barua huanza kwa anwani na tarehe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI.M8_INS_FORMAL_T2', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI', 'Writes to a friend in the stiff words of an official letter (Mheshimiwa, Kuhusu:, Wako mtiifu).', '{"question":"Ni salamu ipi inafaa katika barua kwa rafiki?","wrong_answer":"Mheshimiwa Bwana,","correct_answer":"Mpendwa rafiki yangu Amina,"}'::jsonb, 'The child has seen official letters at school and thinks every letter is written that way.', 'The question "Ni salamu ipi inafaa katika barua kwa rafiki?" with "Mheshimiwa Bwana," among the options.', 'Put a friendly and an official letter side by side; the child highlights the words that differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI.M8_INS_NOASK_T2', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI', 'Starts with the news straight after the greeting, with no asking after the friend (maulizo ya hali).', '{"question":"Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?","wrong_answer":"Nataka kukueleza kuhusu safari yetu.","correct_answer":"Hujambo? Natumai u buheri wa afya."}'::jsonb, 'The child goes to what he wants to say, as in a text message.', 'The question "Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?" with "Nataka kukueleza kuhusu safari yetu." among the options.', 'Order the parts on cards: anwani, tarehe, salamu, maulizo ya hali, ujumbe, hitimisho, jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI.M8_INS_DATE_T2', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI', 'Leaves out the date or writes it in the middle of the letter.', '{"question":"Tarehe huandikwa wapi katika barua ya kirafiki?","wrong_answer":"mwishoni, baada ya jina","correct_answer":"chini ya anwani ya mwandishi, upande wa kulia juu"}'::jsonb, 'The date is not part of what the child wants to say, so he forgets it.', 'The question "Tarehe huandikwa wapi katika barua ya kirafiki?" with "mwishoni, baada ya jina" among the options.', 'Label a model letter; the child places a date card on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI.M8_INS_SIGN_T2', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.KUANDIKA_SHUKRANI', 'Ends with "Wako mtiifu" and a full name and title, as in an official letter.', '{"question":"Ni hitimisho lipi linafaa katika barua kwa rafiki?","wrong_answer":"Wako mtiifu, Bw. Juma Hamisi","correct_answer":"Ni mimi rafiki yako, Juma"}'::jsonb, 'Again the official model is the only one the child has copied.', 'The question "Ni hitimisho lipi linafaa katika barua kwa rafiki?" with "Wako mtiifu, Bw. Juma Hamisi" among the options.', 'Collect three friendly closings and keep them in the exercise book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI.M8_BH_VAGUE', 'KISW.G8.KUANDI.T2_BARUA_YA_KIRAFIKI.BARUA_SHUKRANI', 'Thanks in general words without saying what for (Asante kwa kila kitu).', '{"question":"Ni sentensi ipi bora katika barua ya shukrani?","wrong_answer":"Asante kwa kila kitu.","correct_answer":"Asante kwa kunieleza jinsi ya kumeza dawa kwa wakati; sasa nimepona."}'::jsonb, 'The child thinks thanking is enough.', 'The question "Ni sentensi ipi bora katika barua ya shukrani?" with "Asante kwa kila kitu." among the options.', 'Name what was done and what it changed for you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI.M_KS8_VU_ULIZA', 'KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI', 'Uses an interrogative as a statement.', '{"question":"Ni kiwakilishi kipi kinauliza kuhusu mtu?","wrong_answer":"yeye","correct_answer":"nani"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "yeye" next to the right answer and ask the question again in a new sentence.', 'Nani huuliza kuhusu mtu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI.M_KS8_VU_NINI', 'KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI', 'Mixes nani and nini.', '{"question":"Ni kiwakilishi kipi kinauliza kuhusu kitu?","wrong_answer":"nani","correct_answer":"nini"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "nani" next to the right answer and ask the question again in a new sentence.', 'Nini huuliza kuhusu kitu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI.M_KS8_VU_SIFA', 'KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI', 'Does not know the sifa pronoun.', '{"question":"Katika \"Mrefu amefika\", mrefu ni nini?","wrong_answer":"kivumishi","correct_answer":"kiwakilishi cha sifa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kivumishi" next to the right answer and ask the question again in a new sentence.', 'Mrefu hapa linasimama badala ya nomino.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI.M8_VU_PEKEE', 'KISW.G8.SARUFI.T2_VIWAKILISHI.VIW_ULIZI', 'Uses -enyewe (the pronoun of "self") with the wrong class (kitabu mwenyewe for kitabu chenyewe).', '{"question":"Jaza: Kitabu ___ kimeanguka.","wrong_answer":"mwenyewe","correct_answer":"chenyewe"}'::jsonb, 'Mwenyewe is the first form learnt and covers all classes for the child.', 'The question "Jaza: Kitabu ___ kimeanguka." with "mwenyewe" among the options.', 'Class prefix + -enyewe: mwenyewe (mtu), chenyewe (kitu), lenyewe (jiwe).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T3_HADITHI.MIGHANI.M8_FSI_KIND_T3', 'KISW.G8.KUSIKI.T3_HADITHI.MIGHANI', 'Mixes the two kinds (mighani and visasili) and their purposes.', '{"question":"\"Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni\" ni hadithi ya aina gani?","wrong_answer":"visasili","correct_answer":"mighani"}'::jsonb, 'Both are hadithi; the child has not fixed what each is for and when it is used.', 'The question ""Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni" ni hadithi ya aina gani?" with "visasili" among the options.', 'List for each kind: who uses it, when, and why; sort examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T3_HADITHI.MIGHANI.M8_FSI_WRITTEN_T3', 'KISW.G8.KUSIKI.T3_HADITHI.MIGHANI', 'Calls hadithi written literature because it is found in a textbook.', '{"question":"Hadithi ni utanzu wa fasihi ipi?","wrong_answer":"fasihi andishi","correct_answer":"fasihi simulizi"}'::jsonb, 'The child meets it on the page in class.', 'The question "Hadithi ni utanzu wa fasihi ipi?" with "fasihi andishi" among the options.', 'Ask: who first made it, and how was it passed on? By mouth, from one generation to the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T3_HADITHI.MIGHANI.M8_FSI_OCCASION_T3', 'KISW.G8.KUSIKI.T3_HADITHI.MIGHANI', 'Places the hadithi in the wrong occasion (a lullaby at a work party, a work song at a funeral).', '{"question":"Mighani hutumika lini?","wrong_answer":"wakati wowote","correct_answer":"kusimulia historia ya shujaa wa jamii na kumsifu"}'::jsonb, 'The occasion is not stated in the text, and the child does not link form to use.', 'The question "Mighani hutumika lini?" with "wakati wowote" among the options.', 'Act out the occasion; which kind fits it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T3_HADITHI.MIGHANI.M8_FSI_MESSAGE_T3', 'KISW.G8.KUSIKI.T3_HADITHI.MIGHANI', 'Gives a line of the text as its message instead of the lesson.', '{"question":"Ujumbe wa \"Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni\" ni upi?","wrong_answer":"Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni","correct_answer":"ushujaa na ulinzi wa jamii huheshimiwa."}'::jsonb, 'Copying a line feels like a safe answer.', 'The question "Ujumbe wa "Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni" ni upi?" with "Fumo Liyongo, shujaa wa Pate aliyeshindwa tu kwa sindano ya shaba kitovuni" among the options.', 'Close the text; say the lesson in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU.M8_FAS_GENRE_T3', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU', 'Takes a tamthilia for another kind of text (novela) or gives the features of the other kind.', '{"question":"Ni sifa ipi ni ya tamthilia?","wrong_answer":"husimuliwa na msimulizi bila mazungumzo","correct_answer":"huandikwa kwa mazungumzo ya wahusika ili iigizwe jukwaani"}'::jsonb, 'The child has met several kinds of literature and keeps one list of features for all of them.', 'The question "Ni sifa ipi ni ya tamthilia?" with "husimuliwa na msimulizi bila mazungumzo" among the options.', 'Lay a tamthilia and a novela side by side and list what only the tamthilia has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU.M8_FAS_ORAL_T3', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU', 'Calls a tamthilia oral literature (fasihi simulizi) because it can be read aloud or acted.', '{"question":"Tamthilia ni utanzu wa fasihi ipi?","wrong_answer":"fasihi simulizi","correct_answer":"fasihi andishi"}'::jsonb, 'Plays are acted and poems are recited, so the child thinks of them as spoken.', 'The question "Tamthilia ni utanzu wa fasihi ipi?" with "fasihi simulizi" among the options.', 'Ask: was it first composed in writing by a known author? Then it is fasihi andishi, even when performed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU.M8_FAS_ONEFEATURE_T3', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU', 'Gives one feature only (length, or rhyme) as the whole meaning of a tamthilia.', '{"question":"Eleza maana ya tamthilia.","wrong_answer":"ni mchezo","correct_answer":"ni kazi ya fasihi andishi iliyoandikwa kwa mazungumzo ili iigizwe jukwaani"}'::jsonb, 'The child remembers the most visible feature.', 'The question "Eleza maana ya tamthilia." with "ni mchezo" among the options.', 'Build the definition from three parts: what kind of text, its form, its purpose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU.M8_FAS_AUTHOR_T3', 'KISW.G8.KUSOMA.T3_KUSOMA_KWA_KINA.TAMTHILIA_UTANZU', 'Takes the narrator or a character for the author of the tamthilia.', '{"question":"Ni nani mwandishi wa \"Kilio cha Msitu\"?","wrong_answer":"Bi. Zuhura","correct_answer":"mtunzi aliyetajwa jaladani"}'::jsonb, 'The narrator speaks as "I" and the child takes that voice for the writer.', 'The question "Ni nani mwandishi wa "Kilio cha Msitu"?" with "Bi. Zuhura" among the options.', 'Find the author''s name on the cover; the narrator and characters are inside the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU.M8_INS_AYA_T3', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU', 'Puts several ideas in one paragraph, or one idea across many tiny paragraphs, so no idea is built up.', '{"question":"Aya nzuri ya insha \"Tembo Aliyekosa Maji\" ina nini?","wrong_answer":"mawazo mengi tofauti","correct_answer":"wazo moja kuu linalokuzwa kwa maelezo na mifano"}'::jsonb, 'Paragraphs are made where the child pauses, not where an idea ends.', 'The question "Aya nzuri ya insha "Tembo Aliyekosa Maji" ina nini?" with "mawazo mengi tofauti" among the options.', 'Topic sentence first; then two or three sentences that develop only it; a link to the next paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU.M8_INS_VIDOKEZO_T3', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU', 'Plans with points (vidokezo) that do not belong to the title, or writes the insha without using the points planned.', '{"question":"Ni kidokezo kipi hakifai kwa insha \"Tembo Aliyekosa Maji\"?","wrong_answer":"Bei ya sukari imepanda dukani.","correct_answer":"tembo alikosa maji"}'::jsonb, 'The child lists whatever comes to mind and does not check each point against the title.', 'The question "Ni kidokezo kipi hakifai kwa insha "Tembo Aliyekosa Maji"?" with "Bei ya sukari imepanda dukani." among the options.', 'Write the title at the top of the plan; tick each point only if it helps to tell that story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU.M8_INS_ORDER_T3', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Tembo Aliyekosa Maji\"?","wrong_answer":"walinzi walimwongoza mtoni, wanakijiji waliogopa, alifika kijijini, tembo alikosa maji","correct_answer":"tembo alikosa maji, alifika kijijini, wanakijiji waliogopa, walinzi walimwongoza mtoni"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Tembo Aliyekosa Maji"?" with "walinzi walimwongoza mtoni, wanakijiji waliogopa, alifika kijijini, tembo alikosa maji" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU.M8_INS_END_T3', 'KISW.G8.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_WAZO_KUU', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Tembo Aliyekosa Maji\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza mengi kuhusu jambo hili."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Tembo Aliyekosa Maji"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI.M_KS8_VM_MILIKI', 'KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI', 'Mixes kimilikishi and kisisitizi.', '{"question":"Ni kiwakilishi kimilikishi kipi?","wrong_answer":"mwenyewe","correct_answer":"changu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mwenyewe" next to the right answer and ask the question again in a new sentence.', 'Changu ni kimilikishi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI.M_KS8_VM_SISITIZI', 'KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI', 'Mixes kisisitizi and kimilikishi.', '{"question":"Ni kiwakilishi kisisitizi kipi?","wrong_answer":"changu","correct_answer":"mwenyewe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "changu" next to the right answer and ask the question again in a new sentence.', 'Mwenyewe ni kisisitizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI.M_KS8_VM_UPATANISHO', 'KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI', 'Wrong agreement of possessive.', '{"question":"Kamilisha: kitabu ___ (changu/wangu)","wrong_answer":"wangu","correct_answer":"changu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wangu" next to the right answer and ask the question again in a new sentence.', 'Kitabu hupatana na changu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI.M8_VM_STANDALONE', 'KISW.G8.SARUFI.T3_VIWAKILISHI.VIW_MILIKISHI', 'Leaves the possessive pronoun without its class prefix when it stands alone (Angu kimepotea for Changu kimepotea).', '{"question":"Jaza (kitabu, mimi): ___ kimepotea.","wrong_answer":"Angu","correct_answer":"Changu"}'::jsonb, 'Without the noun in front, the child forgets the prefix.', 'The question "Jaza (kitabu, mimi): ___ kimepotea." with "Angu" among the options.', 'Say the noun silently first, then drop it but keep its prefix: (kitabu) changu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T4_HADITHI.VISASILI.M8_FSI_FORMULA_T4', 'KISW.G8.KUSIKI.T4_HADITHI.VISASILI', 'Starts or ends without the opening or closing formula (Paukwa!).', '{"question":"Msimulizi anaanzaje?","wrong_answer":"anaanza moja kwa moja na kisa","correct_answer":"\"Paukwa!\" na hadhira hujibu \"Pakawa!\""}'::jsonb, 'Telling has been practised as reading a text aloud.', 'The question "Msimulizi anaanzaje?" with "anaanza moja kwa moja na kisa" among the options.', 'Practise the formula with the class answering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T4_HADITHI.VISASILI.M8_FSI_FLAT_T4', 'KISW.G8.KUSIKI.T4_HADITHI.VISASILI', 'Presents in one flat voice, with no change for characters or feelings.', '{"question":"Unapowasilisha, sauti yako iweje?","wrong_answer":"moja tangu mwanzo hadi mwisho","correct_answer":"ibadilike kulingana na mhusika na hisia"}'::jsonb, 'The child is shy and keeps the voice safe.', 'The question "Unapowasilisha, sauti yako iweje?" with "moja tangu mwanzo hadi mwisho" among the options.', 'Give each character a voice; rehearse one line in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T4_HADITHI.VISASILI.M8_FSI_GESTURE_T4', 'KISW.G8.KUSIKI.T4_HADITHI.VISASILI', 'Uses no gestures, or gestures that do not match the words.', '{"question":"Ni ishara ipi inafaa unapotaja \"mlima mrefu\"?","wrong_answer":"kushika kichwa","correct_answer":"kuinua mkono juu juu"}'::jsonb, 'The body is forgotten under the stress of remembering words.', 'The question "Ni ishara ipi inafaa unapotaja "mlima mrefu"?" with "kushika kichwa" among the options.', 'Mirror pairs: one says, one shows; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T4_HADITHI.VISASILI.M8_FSI_NOAUDIENCE_T4', 'KISW.G8.KUSIKI.T4_HADITHI.VISASILI', 'Presents to the floor or the teacher only, with no eye contact and no call for responses.', '{"question":"Unawasilisha mbele ya darasa. Unawaangalia nani?","wrong_answer":"chini au mwalimu peke yake","correct_answer":"hadhira yote, ukiwashirikisha"}'::jsonb, 'Reciting for marks is done to the teacher.', 'The question "Unawasilisha mbele ya darasa. Unawaangalia nani?" with "chini au mwalimu peke yake" among the options.', 'Divide the room into three; look at each part in turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_WORDBYWORD_T4', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Wakulima walichimba mitaro ili kuhifadhi maji ya mvua.\"?","wrong_answer":"Wakulima ... walichimba ... mitaro ... ili ... kuhifadhi ... maji ... ya ... mvua.","correct_answer":"Wakulima walichimba mitaro ili kuhifadhi maji ya mvua."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Wakulima walichimba mitaro ili kuhifadhi maji ya mvua."?" with "Wakulima ... walichimba ... mitaro ... ili ... kuhifadhi ... maji ... ya ... mvua." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_RACE_T4', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_FLAT_T4', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, tutaacha misitu yetu iangamie?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, tutaacha misitu yetu iangamie?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_NOPAUSE_T4', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Lo, mto umerudi kutiririka!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Lo, mto umerudi kutiririka!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_SOUND_T4', 'KISW.G8.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (rasilimali read as lasilimali).', '{"question":"Neno \"rasilimali\" linatamkwa vipi?","wrong_answer":"lasilimali","correct_answer":"rasilimali"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "rasilimali" linatamkwa vipi?" with "lasilimali" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU.M8_INS_LUGHA_T4', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Siku Mto Ulipofurika\"?","wrong_answer":"Maji yalikuwa mengi.","correct_answer":"Maji yalinguruma kama simba mwenye njaa yakimeza mashamba yote."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Siku Mto Ulipofurika"?" with "Maji yalikuwa mengi." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU.M8_INS_WAHUSIKA_T4', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU', 'Gives the characters no names, no features and no words of their own, so the reader cannot see them.', '{"question":"Ni sentensi ipi inamjenga mhusika vizuri katika insha \"Siku Mto Ulipofurika\"?","wrong_answer":"Mtu mmoja alikuja.","correct_answer":"Mzee Juma, mwenye ndevu nyeupe na fimbo ya mpingo, alisimama mlangoni."}'::jsonb, 'The child thinks of the events, not the people in them.', 'The question "Ni sentensi ipi inamjenga mhusika vizuri katika insha "Siku Mto Ulipofurika"?" with "Mtu mmoja alikuja." among the options.', 'For each character: a name, one look, one trait shown by an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU.M8_INS_MANDHARI_T4', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU', 'Gives no setting (time and place) or one that does not fit the events.', '{"question":"Ni mwanzo upi unaonyesha mandhari ya insha \"Siku Mto Ulipofurika\"?","wrong_answer":"Kisa hiki kilitokea.","correct_answer":"Ilikuwa jioni ya Ijumaa katika soko la Gikomba, watu wakiwa wamesongamana."}'::jsonb, 'The child starts with the action.', 'The question "Ni mwanzo upi unaonyesha mandhari ya insha "Siku Mto Ulipofurika"?" with "Kisa hiki kilitokea." among the options.', 'Answer lini? wapi? hali gani? in the first paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU.M8_INS_HISIA_T4', 'KISW.G8.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_MBINU', 'States feelings with one word (nilihuzunika) and never shows them, so the reader feels nothing.', '{"question":"Ni sentensi ipi inamgusa msomaji zaidi?","wrong_answer":"Nilihuzunika.","correct_answer":"Machozi yalinitiririka nilipoona kibanda chetu kikiteketea."}'::jsonb, 'Showing a feeling needs words for the body and the scene.', 'The question "Ni sentensi ipi inamgusa msomaji zaidi?" with "Nilihuzunika." among the options.', 'Turn "nilihuzunika" into what the body did and what was seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_KS8_MT_HU', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Thinks hu- shows a finished act.', '{"question":"Katika \"Huenda sokoni kila siku\", hali ni ipi?","wrong_answer":"timilifu","correct_answer":"ya mazoea"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "timilifu" next to the right answer and ask the question again in a new sentence.', 'Hu- huonyesha mazoea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_KS8_MT_ME', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Thinks -me- shows habit.', '{"question":"Katika \"Amefika\", hali ni ipi?","wrong_answer":"ya mazoea","correct_answer":"timilifu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya mazoea" next to the right answer and ask the question again in a new sentence.', '-me- huonyesha tendo lililokamilika.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_KS8_MT_LI', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Thinks -li- is timilifu.', '{"question":"Katika \"Alifika\", ni hali gani?","wrong_answer":"timilifu","correct_answer":"wakati uliopita rahisi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "timilifu" next to the right answer and ask the question again in a new sentence.', '-li- ni wakati uliopita rahisi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M8_MT_HU_NEG_TIME', 'KISW.G8.SARUFI.T4_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Uses hu- with a time word of one moment (Jana huenda shuleni).', '{"question":"Jaza: Kila Jumamosi tu___ (fua) nguo.","wrong_answer":"tulifua","correct_answer":"hufua"}'::jsonb, 'The child uses the tense of the time word he sees, not the meaning of "kila".', 'The question "Jaza: Kila Jumamosi tu___ (fua) nguo." with "tulifua" among the options.', 'Kila siku, kila Jumamosi, mara nyingi point to a habit: hu-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO.M_KS8_LS_MAAGIZO_DETAIL', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO.M_KS8_LS_MAAGIZO_OPPOSITE', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO.M_KS8_LS_MAAGIZO_NOTSAID', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO.M8_LSG_LS_MAAGIZO', 'KISW.G8.KUSIKI.T5_KUSIKILIZA_MAAGIZO.LS_MAAGIZO', 'Does the steps of the instructions in the wrong order or skips one.', '{"question":"Ulisikia: \"Kwanza osha mikono, kisha paka sabuni, mwishowe suuza.\" Unaanza na nini?","wrong_answer":"paka sabuni","correct_answer":"osha mikono"}'::jsonb, 'The child remembers the steps, not their order.', 'The question "Ulisikia: "Kwanza osha mikono, kisha paka sabuni, mwishowe suuza." Unaanza na nini?" with "paka sabuni" among the options.', 'Number the steps on fingers while listening; repeat them back before acting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS8_RS_UFAHAMU5_DETAIL', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS8_RS_UFAHAMU5_OPPOSITE', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS8_RS_UFAHAMU5_NOTSAID', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M8_UFH_RS_UFAHAMU5', 'KISW.G8.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Writes a summary answer that copies a whole paragraph.', '{"question":"Eleza kwa ufupi aya ya pili inahusu nini.","wrong_answer":"kunakili aya yote","correct_answer":"sentensi moja yenye wazo kuu la aya"}'::jsonb, 'Copying feels safe.', 'The question "Eleza kwa ufupi aya ya pili inahusu nini." with "kunakili aya yote" among the options.', 'Close the passage; say the main idea in one sentence; then check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M8_INS_NOVIFAA_T5', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Starts the steps without saying what is needed (vifaa) or what the instructions are for.', '{"question":"Maelekezo ya \"Jinsi ya Kupika Chakula cha Familia Pamoja\" huanza na nini?","wrong_answer":"hatua ya kwanza moja kwa moja","correct_answer":"lengo la maelekezo na vifaa vinavyohitajika"}'::jsonb, 'The child goes straight to doing.', 'The question "Maelekezo ya "Jinsi ya Kupika Chakula cha Familia Pamoja" huanza na nini?" with "hatua ya kwanza moja kwa moja" among the options.', 'Plan: lengo, vifaa, hatua, tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M8_INS_STORYFORM_T5', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Tells what he did in the past (Nilichukua..., nilikoroga...) instead of giving instructions (Chukua..., koroga...).', '{"question":"Ni sentensi ipi inafaa katika insha ya maelekezo?","wrong_answer":"Nilichukua sufuria nikaweka maji.","correct_answer":"Chukua sufuria na uweke maji."}'::jsonb, 'The child turns instructions into a story of his own day.', 'The question "Ni sentensi ipi inafaa katika insha ya maelekezo?" with "Nilichukua sufuria nikaweka maji." among the options.', 'Underline the verbs; change each to the command or -e form (chukua, weka; uchukue).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M8_INS_ORDER_M_T5', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Gives the steps in an order that cannot work, with no signal words.', '{"question":"Ni mpangilio upi unafaa katika \"Jinsi ya Kupika Chakula cha Familia Pamoja\"?","wrong_answer":"pakua na mle pamoja, andaa mboga na nafaka, osha vyombo na mikono, gawanya kazi kwa wote","correct_answer":"gawanya kazi kwa wote, osha vyombo na mikono, andaa mboga na nafaka, pakua na mle pamoja"}'::jsonb, 'The child lists steps as he remembers them.', 'The question "Ni mpangilio upi unafaa katika "Jinsi ya Kupika Chakula cha Familia Pamoja"?" with "pakua na mle pamoja, andaa mboga na nafaka, osha vyombo na mikono, gawanya kazi kwa wote" among the options.', 'Act out the steps; number them; add kwanza, kisha, baadaye, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M8_INS_NOWARN_T5', 'KISW.G8.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Leaves out safety warnings where the task needs them.', '{"question":"Ni kipi kinakosekana katika maelekezo ya \"Jinsi ya Kupika Chakula cha Familia Pamoja\"?","wrong_answer":"anwani","correct_answer":"tahadhari ya usalama"}'::jsonb, 'Warnings are not part of the steps, so they are forgotten.', 'The question "Ni kipi kinakosekana katika maelekezo ya "Jinsi ya Kupika Chakula cha Familia Pamoja"?" with "anwani" among the options.', 'Ask at each step: what could go wrong? Write a tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI.M_KS8_TW_PAST', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI', 'Mixes the two perfect tenses.', '{"question":"Ni sentensi ipi iko katika uliopita timilifu?","wrong_answer":"Atakuwa amefika","correct_answer":"Alikuwa amefika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Atakuwa amefika" next to the right answer and ask the question again in a new sentence.', 'Alikuwa amefika ni uliopita timilifu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI.M_KS8_TW_FUT', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI', 'Mixes the two perfect tenses.', '{"question":"Ni sentensi ipi iko katika ujao timilifu?","wrong_answer":"Alikuwa amefika","correct_answer":"Atakuwa amefika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alikuwa amefika" next to the right answer and ask the question again in a new sentence.', 'Atakuwa amefika ni ujao timilifu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI.M_KS8_TW_SIMPLE', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI', 'Takes the simple tense as perfect.', '{"question":"Ni sentensi ipi ni timilifu?","wrong_answer":"Alifika jana","correct_answer":"Alikuwa amefika jana"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alifika jana" next to the right answer and ask the question again in a new sentence.', 'Timilifu ina ame- baada ya alikuwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI.M8_TW_MARKER_BOTH', 'KISW.G8.SARUFI.T5_NYAKATI_NA_HALI.TIMILIFU_WAKATI', 'Puts the time marker on both verbs (alikuwa alimefika) instead of on kuwa only.', '{"question":"Jaza: Tulipofika, mgeni ___ (fika) tayari.","wrong_answer":"alikuwa alifika","correct_answer":"alikuwa amefika"}'::jsonb, 'The child marks the past twice to be sure.', 'The question "Jaza: Tulipofika, mgeni ___ (fika) tayari." with "alikuwa alifika" among the options.', 'Time on kuwa (-li-, -ta-), completion on the main verb (-me-).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE.M_KS8_LS_UJUMBE_DETAIL', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE.M_KS8_LS_UJUMBE_OPPOSITE', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE.M_KS8_LS_UJUMBE_NOTSAID', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE.M8_LSU_LS_UJUMBE', 'KISW.G8.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_UJUMBE', 'Gives the first sentence he heard as the message.', '{"question":"Ujumbe wa ufahamu wa kusikiliza ni upi?","wrong_answer":"sentensi ya kwanza aliyosikia","correct_answer":"funzo kuu la habari yote"}'::jsonb, 'The opening is remembered best.', 'The question "Ujumbe wa ufahamu wa kusikiliza ni upi?" with "sentensi ya kwanza aliyosikia" among the options.', 'Listen to the end; then ask what the speaker wants us to know or do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI.M8_FAS_SWAP_T6', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI', 'Swaps maudhui (the issues the work is about) and dhamira (what the author aims to teach).', '{"question":"Katika \"Kilio cha Msitu\", \"kuhimiza jamii kutunza msitu na kupinga ufisadi\" ni maudhui au dhamira?","wrong_answer":"maudhui","correct_answer":"dhamira"}'::jsonb, 'The two words are taught together and both answer "what is it about?"', 'The question "Katika "Kilio cha Msitu", "kuhimiza jamii kutunza msitu na kupinga ufisadi" ni maudhui au dhamira?" with "maudhui" among the options.', 'Maudhui: the issues raised (ufisadi, elimu). Dhamira: the author''s aim (kuonya, kuhimiza). Sort sentences into the two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI.M8_FAS_TITLE_T6', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI', 'Gives the title or the setting of the work as its maudhui.', '{"question":"Ni ipi ni maudhui katika \"Kilio cha Msitu\"?","wrong_answer":"Kilio cha Msitu","correct_answer":"uharibifu wa mazingira na ufisadi"}'::jsonb, 'The title is the only phrase about the whole work the child is sure of.', 'The question "Ni ipi ni maudhui katika "Kilio cha Msitu"?" with "Kilio cha Msitu" among the options.', 'Ask what issue the characters face and argue about; that is the maudhui.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI.M8_FAS_EVENT_T6', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI', 'Gives one event of the story as its maudhui.', '{"question":"Maudhui ya \"Kilio cha Msitu\" ni yapi?","wrong_answer":"Zuhura anazuia malori ya mbao","correct_answer":"uharibifu wa mazingira na ufisadi"}'::jsonb, 'The event is memorable; the child has not moved from what happened to what it is about.', 'The question "Maudhui ya "Kilio cha Msitu" ni yapi?" with "Zuhura anazuia malori ya mbao" among the options.', 'Ask: this event shows which issue? Write the issue in one or two words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI.M8_FAS_OUTSIDE_T6', 'KISW.G8.KUSOMA.T6_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MAUDHUI', 'States a lesson from his own life or religion that the work does not raise.', '{"question":"Kwa mujibu wa \"Kilio cha Msitu\", mwandishi analenga nini?","wrong_answer":"kutuhimiza tuende kanisani au msikitini kila wiki","correct_answer":"kuhimiza jamii kutunza msitu na kupinga ufisadi"}'::jsonb, 'The question sounds like a moral question and the child gives a moral he knows.', 'The question "Kwa mujibu wa "Kilio cha Msitu", mwandishi analenga nini?" with "kutuhimiza tuende kanisani au msikitini kila wiki" among the options.', 'Ask for the part of the text that shows the aim.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO.M8_INS_CHANGE_T6', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO', 'Changes the words he was given to start or end with.', '{"question":"Umepewa: \"Nilipofungua mlango, moshi mzito ulinikaribisha.\" kama mwanzo. Ufanye nini?","wrong_answer":"anza kwa sentensi yako inayofanana nayo","correct_answer":"anza kwa maneno hayo hasa bila kuyabadilisha"}'::jsonb, 'The child copies the idea, not the exact words.', 'The question "Umepewa: "Nilipofungua mlango, moshi mzito ulinikaribisha." kama mwanzo. Ufanye nini?" with "anza kwa sentensi yako inayofanana nayo" among the options.', 'Copy the given words first, then continue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO.M8_INS_PLACE_T6', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO', 'Puts the given ending in the middle of the insha, or the given opening at the end.', '{"question":"Insha ya mdokezo wa kumalizia: maneno uliyopewa yawekwe wapi?","wrong_answer":"katikati ya insha","correct_answer":"mwishoni kabisa mwa insha"}'::jsonb, 'The two kinds of mdokezo are not told apart.', 'The question "Insha ya mdokezo wa kumalizia: maneno uliyopewa yawekwe wapi?" with "katikati ya insha" among the options.', 'Label the two kinds: mdokezo wa kuanzia and wa kumalizia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO.M8_INS_NOLEAD_T6', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO', 'Writes a story that does not lead to the given ending.', '{"question":"Insha inaishia: \"Nilipofungua mlango, moshi mzito ulinikaribisha.\" Kisa kiwe vipi?","wrong_answer":"kisa chochote kisha kuweka maneno hayo mwishoni","correct_answer":"kisa ambacho matukio yake yanaelekea kwenye maneno hayo"}'::jsonb, 'The ending is added like a sticker.', 'The question "Insha inaishia: "Nilipofungua mlango, moshi mzito ulinikaribisha." Kisa kiwe vipi?" with "kisa chochote kisha kuweka maneno hayo mwishoni" among the options.', 'Plan backwards: what must happen for this ending to make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO.M8_INS_TENSE_M_T6', 'KISW.G8.KUANDI.T6_INSHA_ZA_KUBUNI.MDOKEZO', 'Mixes tenses between the given words and his own story.', '{"question":"Mdokezo uko katika wakati uliopita. Insha yako iweje?","wrong_answer":"katika wakati uliopo","correct_answer":"katika wakati uliopita kama mdokezo"}'::jsonb, 'The child writes in the tense he likes.', 'The question "Mdokezo uko katika wakati uliopita. Insha yako iweje?" with "katika wakati uliopo" among the options.', 'Check the tense of the given words; keep it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA.M_KS8_VS_SIFA', 'KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA', 'Mixes sifa and kuashiria.', '{"question":"Ni kivumishi cha sifa kipi?","wrong_answer":"huyu","correct_answer":"mzuri"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "huyu" next to the right answer and ask the question again in a new sentence.', 'Mzuri ni kivumishi cha sifa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA.M_KS8_VS_ASHIRIA', 'KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA', 'Mixes kuashiria and sifa.', '{"question":"Ni kivumishi cha kuashiria kipi?","wrong_answer":"mzuri","correct_answer":"huyu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mzuri" next to the right answer and ask the question again in a new sentence.', 'Huyu ni kivumishi cha kuashiria.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA.M_KS8_VS_NAFASI', 'KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA', 'Puts the adjective before the noun.', '{"question":"Ni sentensi ipi imepangwa sawa?","wrong_answer":"Mzuri mtoto","correct_answer":"Mtoto mzuri"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mzuri mtoto" next to the right answer and ask the question again in a new sentence.', 'Kivumishi hufuata nomino.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA.M8_VS_LOAN_AGREE', 'KISW.G8.SARUFI.T6_VIVUMISHI.VIVUMISHI_SIFA', 'Puts a class prefix on a loan adjective that never takes one (msafi is right, but mghali, kighali for ghali; mlaini for laini).', '{"question":"Jaza: Dawa hii ni ___ (ghali).","wrong_answer":"nghali","correct_answer":"ghali"}'::jsonb, 'The child applies the agreement rule to every adjective, including Arabic and other loans that do not change.', 'The question "Jaza: Dawa hii ni ___ (ghali)." with "nghali" among the options.', 'Make a list of adjectives that never change (ghali, safi in some uses, laini, hodari, imara).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI.M8_ORL_NOPARAPHRASE_T7', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI', 'Does not show he has understood (no paraphrase or question) and moves to his own story.', '{"question":"Mwenzako anakueleza tatizo lake. Ni jibu lipi la usikilizaji husishi?","wrong_answer":"Hilo si kitu, mimi nilikuwa na tatizo kubwa zaidi...","correct_answer":"Kwa hiyo unasema unahisi upweke shuleni? Pole sana."}'::jsonb, 'The child wants to share his own story.', 'The question "Mwenzako anakueleza tatizo lake. Ni jibu lipi la usikilizaji husishi?" with "Hilo si kitu, mimi nilikuwa na tatizo kubwa zaidi..." among the options.', 'Practise "Kwa hiyo unasema..." before any reply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI.M8_ORL_JUDGE_T7', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI', 'Judges or advises at once instead of listening first.', '{"question":"Rafiki ana huzuni. Unaanza kwa?","wrong_answer":"Hupaswi kuhuzunika!","correct_answer":"Nieleze kilichotokea, nakusikiliza."}'::jsonb, 'Advice feels like help.', 'The question "Rafiki ana huzuni. Unaanza kwa?" with "Hupaswi kuhuzunika!" among the options.', 'Listen, reflect, then ask before advising.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI.M8_ORL_INTERRUPT_T7', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI.M8_ORL_EYES_T7', 'KISW.G8.KUSIKI.T7_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T7_.KUFUPISHA.M8_UFP_COPY_T7', 'KISW.G8.KUSOMA.T7_.KUFUPISHA', 'Copies whole sentences from the passage into the summary.', '{"question":"Ufupisho mzuri huandikwa vipi?","wrong_answer":"kunakili sentensi muhimu kutoka kifungu","correct_answer":"kwa maneno yako mwenyewe bila kupoteza maana"}'::jsonb, 'Copying feels safe; the child fears changing the meaning.', 'The question "Ufupisho mzuri huandikwa vipi?" with "kunakili sentensi muhimu kutoka kifungu" among the options.', 'Read, close the passage, write the point; then check it against the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T7_.KUFUPISHA.M8_UFP_EXAMPLE_T7', 'KISW.G8.KUSOMA.T7_.KUFUPISHA', 'Keeps the examples and illustrations in the summary.', '{"question":"Ni lipi liingie katika ufupisho?","wrong_answer":"Kwa mfano, shule ya Kilimani ilijenga njia mbili mwaka 2025.","correct_answer":"Shule zinapaswa kujenga njia za kupitisha viti vya magurudumu."}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho?" with "Kwa mfano, shule ya Kilimani ilijenga njia mbili mwaka 2025." among the options.', 'Cross out every "kwa mfano" and every number that only illustrates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T7_.KUFUPISHA.M8_UFP_OPINION_T7', 'KISW.G8.KUSOMA.T7_.KUFUPISHA', 'Adds his own opinion or advice that the passage does not give.', '{"question":"Ni sentensi ipi isiingie katika ufupisho?","wrong_answer":"Shule zinapaswa kujenga njia za kupitisha viti vya magurudumu.","correct_answer":"Mimi nadhani serikali inapaswa kufanya zaidi."}'::jsonb, 'The child wants to show he has views on the topic.', 'The question "Ni sentensi ipi isiingie katika ufupisho?" with "Shule zinapaswa kujenga njia za kupitisha viti vya magurudumu." among the options.', 'Ask of every sentence: did the writer say this?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T7_.KUFUPISHA.M8_UFP_LENGTH_T7', 'KISW.G8.KUSOMA.T7_.KUFUPISHA', 'Goes over the word limit (60 words) or writes in notes with no sentences.', '{"question":"Umeambiwa ufupishe kwa maneno 60. Ufanye nini?","wrong_answer":"andika zaidi ili usiache kitu","correct_answer":"andika sentensi kamili zisizozidi maneno 60"}'::jsonb, 'The child is afraid of leaving out a point.', 'The question "Umeambiwa ufupishe kwa maneno 60. Ufanye nini?" with "andika zaidi ili usiache kitu" among the options.', 'Count words after the first draft; join points that repeat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI.M8_INS_LUGHA_T7', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Kituo cha Watoto Wenye Mahitaji Maalum\"?","wrong_answer":"Kituo kilikuwa kizuri.","correct_answer":"Bustani ya kituo ilikuwa kama zulia la kijani lililotandikwa kwa upendo."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Kituo cha Watoto Wenye Mahitaji Maalum"?" with "Kituo kilikuwa kizuri." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI.M8_INS_DETAIL_T7', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Kituo cha Watoto Wenye Mahitaji Maalum\"?","wrong_answer":"Kituo kilikuwa kizuri.","correct_answer":"Bustani ya kituo ilikuwa kama zulia la kijani lililotandikwa kwa upendo."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Kituo cha Watoto Wenye Mahitaji Maalum"?" with "Kituo kilikuwa kizuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI.M8_INS_MSAMIATI_T7', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Kituo cha Watoto Wenye Mahitaji Maalum\"?","wrong_answer":"Kituo kilikuwa kizuri.","correct_answer":"Bustani ya kituo ilikuwa kama zulia la kijani lililotandikwa kwa upendo."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Kituo cha Watoto Wenye Mahitaji Maalum"?" with "Kituo kilikuwa kizuri." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI.M8_INS_OFFTOPIC_T7', 'KISW.G8.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_TAMATHALI', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Kituo cha Watoto Wenye Mahitaji Maalum\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Bustani ya kituo ilikuwa kama zulia la kijani lililotandikwa kwa upendo."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Kituo cha Watoto Wenye Mahitaji Maalum", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI.M_KS8_VK_MILIKI', 'KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI', 'Mixes possessive and number.', '{"question":"Ni kivumishi kimilikishi kipi?","wrong_answer":"wawili","correct_answer":"wangu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wawili" next to the right answer and ask the question again in a new sentence.', 'Wangu ni kivumishi kimilikishi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI.M_KS8_VK_IDADI', 'KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI', 'Mixes number and possessive.', '{"question":"Ni kivumishi cha idadi kipi?","wrong_answer":"wangu","correct_answer":"watatu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wangu" next to the right answer and ask the question again in a new sentence.', 'Watatu ni kivumishi cha idadi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI.M_KS8_VK_NAFASI', 'KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI', 'Puts it before the noun.', '{"question":"Ni sentensi ipi imepangwa sawa?","wrong_answer":"Wawili watoto","correct_answer":"Watoto wawili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Wawili watoto" next to the right answer and ask the question again in a new sentence.', 'Kivumishi hufuata nomino.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI.M8_VK_ORDER_BOTH', 'KISW.G8.SARUFI.T7_VIVUMISHI.VIVUMISHI_MILIKI', 'Puts the number before the possessive (watoto wawili wangu) where Kiswahili usually says watoto wangu wawili.', '{"question":"Ni mpangilio upi wa kawaida?","wrong_answer":"watoto wawili wangu","correct_answer":"watoto wangu wawili"}'::jsonb, 'English "my two children" is read as noun + number + possessive by some.', 'The question "Ni mpangilio upi wa kawaida?" with "watoto wawili wangu" among the options.', 'Usual order: noun + possessive + number: watoto wangu wawili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO.M8_ORL_NOPLAN_T8', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO', 'Starts talking with no plan and loses the point (ummm... na... ummm).', '{"question":"Umepewa mada ghafla. Ufanye nini kwanza?","wrong_answer":"anza kuzungumza mara moja","correct_answer":"fikiri hoja tatu kwa sekunde chache, kisha anza"}'::jsonb, 'Impromptu is taken to mean unplanned.', 'The question "Umepewa mada ghafla. Ufanye nini kwanza?" with "anza kuzungumza mara moja" among the options.', 'Practise a ten-second plan: mwanzo, hoja mbili, mwisho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO.M8_ORL_FILLERS_T8', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO', 'Fills every pause with "ee", "aa", "si" or "like".', '{"question":"Ni lipi bora unapotafuta neno?","wrong_answer":"kusema \"ee... aa...\" kila mara","correct_answer":"kunyamaza kidogo, kisha kuendelea"}'::jsonb, 'Silence feels like failure.', 'The question "Ni lipi bora unapotafuta neno?" with "kusema "ee... aa..." kila mara" among the options.', 'Count fillers in a recorded talk; try again with pauses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO.M8_ORL_OFFTOPIC_T8', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO', 'Answers or speaks on something other than the topic (jinsi ya kujikinga na wezi wa mtandaoni).', '{"question":"Mada ni jinsi ya kujikinga na wezi wa mtandaoni. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia jinsi ya kujikinga na wezi wa mtandaoni kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni jinsi ya kujikinga na wezi wa mtandaoni. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO.M8_ORL_SLANG_T8', 'KISW.G8.KUSIKI.T8_UZUNGUMZAJI_WA_PAPO_.PAPO_KWA_HAPO', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI.M8_FAS_PLACEONLY_T8', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI', 'Gives only the place as mandhari, and leaves out the time and the social setting.', '{"question":"Mandhari ya \"Kilio cha Msitu\" ni yapi?","wrong_answer":"kijiji cha Msitu Mweusi","correct_answer":"kijiji cha Msitu Mweusi, wakati wa kampeni za uchaguzi"}'::jsonb, 'Mandhari is first taught as "mahali".', 'The question "Mandhari ya "Kilio cha Msitu" ni yapi?" with "kijiji cha Msitu Mweusi" among the options.', 'Make three boxes: mahali, wakati, hali ya kijamii; fill each from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI.M8_FAS_PLOT_LIST_T8', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI', 'Gives a list of the characters, or a summary of the message, as the ploti.', '{"question":"Ploti ya \"Kilio cha Msitu\" ni nini?","wrong_answer":"orodha ya wahusika: Bi. Zuhura na Kazungu","correct_answer":"mfuatano wa matukio tangu mwanzo hadi mwisho"}'::jsonb, 'Ploti is a new word and the child grabs what he knows about the work.', 'The question "Ploti ya "Kilio cha Msitu" ni nini?" with "orodha ya wahusika: Bi. Zuhura na Kazungu" among the options.', 'Ploti is the chain of events with cause: because A, then B. Build it with event cards and arrows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI.M8_FAS_PLOT_ORDER_T8', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI', 'Puts the events of the ploti in the order he remembers them, not the order of the story.', '{"question":"Ni tukio lipi huja kwanza katika ploti ya \"Kilio cha Msitu\"?","wrong_answer":"Zuhura anazuia malori ya mbao","correct_answer":"tukio la mwanzo kabisa la kazi"}'::jsonb, 'The climax is remembered first.', 'The question "Ni tukio lipi huja kwanza katika ploti ya "Kilio cha Msitu"?" with "Zuhura anazuia malori ya mbao" among the options.', 'Number the events on the page; then check the order against the chapters or scenes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI.M8_FAS_NOUSE_T8', 'KISW.G8.KUSOMA.T8_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MANDHARI', 'Names the mandhari but cannot say why it matters to the story (it is "just where it happened").', '{"question":"Mandhari ya kijiji cha Msitu Mweusi yana umuhimu gani katika \"Kilio cha Msitu\"?","wrong_answer":"ni mahali tu hadithi ilipotokea","correct_answer":"yanaonyesha hali ya wahusika na kuchangia uharibifu wa mazingira na ufisadi"}'::jsonb, 'Setting has been taught as a fact to find, not as a tool of the author.', 'The question "Mandhari ya kijiji cha Msitu Mweusi yana umuhimu gani katika "Kilio cha Msitu"?" with "ni mahali tu hadithi ilipotokea" among the options.', 'Ask: could the story happen the same way anywhere else? What does this place add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI.M_KS8_MM_MTAJO', 'KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI', 'Uses brackets for speech.', '{"question":"Ni alama ipi hunukuu maneno halisi ya mtu?","wrong_answer":"mshazari","correct_answer":"alama za mtajo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mshazari" next to the right answer and ask the question again in a new sentence.', 'Alama za mtajo hunukuu maneno halisi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI.M_KS8_MM_MSHAZARI', 'KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI', 'Uses a comma for choices.', '{"question":"Ni alama ipi hutenga machaguo kama ama/au?","wrong_answer":"koma","correct_answer":"mshazari"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "koma" next to the right answer and ask the question again in a new sentence.', 'Mshazari hutenga machaguo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI.M_KS8_MM_TAREHE', 'KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI', 'Does not know dates use slash.', '{"question":"Ni tarehe ipi imeandikwa kwa mshazari?","wrong_answer":"12.11.2026","correct_answer":"12/11/2026"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "12.11.2026" next to the right answer and ask the question again in a new sentence.', 'Mshazari hutumika katika tarehe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI.M8_MM_TITLE', 'KISW.G8.KUANDI.T8_VIAKIFISHI.MTAJO_MSHAZARI', 'Leaves out the quotation marks around the title of a book or a quoted word.', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Nilisoma kitabu cha Kilio cha Msitu.","correct_answer":"Nilisoma kitabu cha \"Kilio cha Msitu\"."}'::jsonb, 'The child knows speech marks for speech only.', 'The question "Ni ipi imeandikwa sawa?" with "Nilisoma kitabu cha Kilio cha Msitu." among the options.', 'Alama za mtajo also mark titles and quoted words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI.M_KS8_GI_UMOJA', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI', 'Uses zi- for the singular.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Nyumba zinapendeza.","correct_answer":"Nyumba inapendeza."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Nyumba zinapendeza." next to the right answer and ask the question again in a new sentence.', 'Umoja wa I-ZI hutumia i-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI.M_KS8_GI_WINGI', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI', 'Uses i- for the plural.', '{"question":"Chagua sentensi sahihi kwa wingi.","wrong_answer":"Nyumba inapendeza sana.","correct_answer":"Nyumba zinapendeza."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Nyumba inapendeza sana." next to the right answer and ask the question again in a new sentence.', 'Wingi wa I-ZI hutumia zi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI.M_KS8_GI_NOMINO', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI', 'Names a wrong noun for the ngeli.', '{"question":"Ni nomino ipi ni ya ngeli ya I-ZI?","wrong_answer":"mtoto","correct_answer":"meza"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mtoto" next to the right answer and ask the question again in a new sentence.', 'Meza ni ya I-ZI.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI.M8_GI_ANIMAL', 'KISW.G8.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_IZI', 'Gives an N-noun animal I-ZI agreement (Ndege inaruka for Ndege anaruka).', '{"question":"Jaza: Ndege ___ (anaruka / inaruka).","wrong_answer":"inaruka","correct_answer":"anaruka"}'::jsonb, 'Ndege looks like nyumba and meza.', 'The question "Jaza: Ndege ___ (anaruka / inaruka)." with "inaruka" among the options.', 'Animals take A-WA agreement whatever their form: ndege anaruka, ndege wanaruka.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SWAP_T9', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /sh/ for /ch/, so chaka (a thicket) becomes shaka (doubt).', '{"question":"Mwalimu anasema: \"chaka\". Umesikia neno lipi?","wrong_answer":"shaka","correct_answer":"chaka"}'::jsonb, 'Several Kenyan first languages (Dholuo among them) have no /sh/ and say s or ch, so the child hears ch and sh as one sound.', 'The question "Mwalimu anasema: "chaka". Umesikia neno lipi?" with "shaka" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SPELL_T9', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (shali where chali is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"lying on one''s back\".","wrong_answer":"shali","correct_answer":"chali"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "lying on one''s back"." with "shali" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SAME_T9', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"chali\" na \"shali\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""chali" na "shali" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_TWISTER_T9', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Mnunuzi aangalie tarehe ya mwisho wa matumizi.","correct_answer":"Shaban alishangaa chai ya Shani ilichemka chini ya shamba la Chacha."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Mnunuzi aangalie tarehe ya mwisho wa matumizi." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M8_MAT_SYLL_T9', 'KISW.G8.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Breaks the word into syllables at the wrong place, so the target sound is lost (ch-aka read as two wrong parts).', '{"question":"Neno \"chaka\" lina silabi zipi?","wrong_answer":"c-haka","correct_answer":"cha-ka"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "chaka" lina silabi zipi?" with "c-haka" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS8_RS_USHAWISHI_DETAIL', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS8_RS_USHAWISHI_OPPOSITE', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS8_RS_USHAWISHI_NOTSAID', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M8_USH_RS_USHAWISHI', 'KISW.G8.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Takes the writer''s claim for a proven fact and does not see the persuading words.', '{"question":"Katika kifungu, \"Kila mtu mwenye busara hutumia simu hii\" ni nini?","wrong_answer":"ukweli uliothibitishwa","correct_answer":"mbinu ya ushawishi"}'::jsonb, 'Strong claims look like facts.', 'The question "Katika kifungu, "Kila mtu mwenye busara hutumia simu hii" ni nini?" with "ukweli uliothibitishwa" among the options.', 'Mark words that push the reader (kila mtu, bora zaidi, usikose).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M8_INS_AYA_T9', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Puts several ideas in one paragraph, or one idea across many tiny paragraphs, so no idea is built up.', '{"question":"Aya nzuri ya insha \"Bidhaa Bandia Sokoni\" ina nini?","wrong_answer":"mawazo mengi tofauti","correct_answer":"wazo moja kuu linalokuzwa kwa maelezo na mifano"}'::jsonb, 'Paragraphs are made where the child pauses, not where an idea ends.', 'The question "Aya nzuri ya insha "Bidhaa Bandia Sokoni" ina nini?" with "mawazo mengi tofauti" among the options.', 'Topic sentence first; then two or three sentences that develop only it; a link to the next paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M8_INS_MTAZAMO_T9', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Switches between "I" and "he" for the narrator, or between views, in one insha.', '{"question":"Ni lipi ni kosa katika insha moja?","wrong_answer":"kuanza \"nilikwenda...\" kisha \"alikwenda...\" kwa msimulizi yuleyule","correct_answer":"kutumia nafsi moja ya msimulizi tangu mwanzo hadi mwisho"}'::jsonb, 'The child forgets who is telling the story.', 'The question "Ni lipi ni kosa katika insha moja?" with "kuanza "nilikwenda..." kisha "alikwenda..." kwa msimulizi yuleyule" among the options.', 'Decide the narrator before writing; circle every verb of the narrator and check the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M8_INS_ORDER_T9', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Bidhaa Bandia Sokoni\"?","wrong_answer":"tuliripoti kwa mamlaka, nilirudi dukani, iliharibika siku ya pili, nilinunua simu","correct_answer":"nilinunua simu, iliharibika siku ya pili, nilirudi dukani, tuliripoti kwa mamlaka"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Bidhaa Bandia Sokoni"?" with "tuliripoti kwa mamlaka, nilirudi dukani, iliharibika siku ya pili, nilinunua simu" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M8_INS_MIX_T9', 'KISW.G8.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Puts English or Sheng words in the insha (tulienda kwa party, mathe, form).', '{"question":"Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?","wrong_answer":"Mathe alinipea form ya kujaza.","correct_answer":"Mama alinipa fomu ya kujaza."}'::jsonb, 'The child speaks a mixed language at home and with friends and does not notice the switch in writing.', 'The question "Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?" with "Mathe alinipea form ya kujaza." among the options.', 'Underline each non-Kiswahili word; find the Kiswahili word together (mama, sherehe, fomu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA.M_KS8_GU_UJI', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA', 'Uses ki- for uji.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Uji kimeiva.","correct_answer":"Uji umeiva."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Uji kimeiva." next to the right answer and ask the question again in a new sentence.', 'Uji ni wa U-U na hutumia u-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA.M_KS8_GU_UGONJWA', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA', 'Uses u- for the plural.', '{"question":"Chagua sentensi sahihi kwa wingi.","wrong_answer":"Magonjwa unaumiza.","correct_answer":"Magonjwa yanaumiza."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Magonjwa unaumiza." next to the right answer and ask the question again in a new sentence.', 'Wingi wa U-YA hutumia ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA.M_KS8_GU_NOMINO', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA', 'Names a wrong noun.', '{"question":"Ni nomino ipi ni ya ngeli ya U-U?","wrong_answer":"kitabu","correct_answer":"ugali"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kitabu" next to the right answer and ask the question again in a new sentence.', 'Ugali ni wa U-U.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA.M8_GU_UZI', 'KISW.G8.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_UU_UYA', 'Puts a U-YA or U-U noun in U-ZI (Ugonjwa huu -> Ngonjwa hizi).', '{"question":"Wingi wa \"ugonjwa huu\" ni?","wrong_answer":"ngonjwa hizi","correct_answer":"magonjwa haya"}'::jsonb, 'U-ZI (ukuta/kuta) is learnt first and its plural rule is copied.', 'The question "Wingi wa "ugonjwa huu" ni?" with "ngonjwa hizi" among the options.', 'Test the plural: ma- means U-YA (magonjwa); no plural means U-U (uji).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA.M8_FSI_KIND_T10', 'KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA', 'Mixes the two kinds (hurafa and hekaya) and their purposes.', '{"question":"\"Sungura na Fisi waliogawana mavuno\" ni hadithi ya aina gani?","wrong_answer":"hekaya","correct_answer":"hurafa"}'::jsonb, 'Both are hadithi; the child has not fixed what each is for and when it is used.', 'The question ""Sungura na Fisi waliogawana mavuno" ni hadithi ya aina gani?" with "hekaya" among the options.', 'List for each kind: who uses it, when, and why; sort examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA.M8_FSI_WRITTEN_T10', 'KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA', 'Calls hadithi written literature because it is found in a textbook.', '{"question":"Hadithi ni utanzu wa fasihi ipi?","wrong_answer":"fasihi andishi","correct_answer":"fasihi simulizi"}'::jsonb, 'The child meets it on the page in class.', 'The question "Hadithi ni utanzu wa fasihi ipi?" with "fasihi andishi" among the options.', 'Ask: who first made it, and how was it passed on? By mouth, from one generation to the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA.M8_FSI_OCCASION_T10', 'KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA', 'Places the hadithi in the wrong occasion (a lullaby at a work party, a work song at a funeral).', '{"question":"Hurafa hutumika lini?","wrong_answer":"wakati wowote","correct_answer":"jioni kuburudisha na kufunza watoto"}'::jsonb, 'The occasion is not stated in the text, and the child does not link form to use.', 'The question "Hurafa hutumika lini?" with "wakati wowote" among the options.', 'Act out the occasion; which kind fits it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA.M8_FSI_MESSAGE_T10', 'KISW.G8.KUSIKI.T10_HADITHI.HURAFA_HEKAYA', 'Gives a line of the text as its message instead of the lesson.', '{"question":"Ujumbe wa \"Sungura na Fisi waliogawana mavuno\" ni upi?","wrong_answer":"Sungura na Fisi waliogawana mavuno","correct_answer":"ujanja wa kudanganya huleta adhabu; tushirikiane kwa haki."}'::jsonb, 'Copying a line feels like a safe answer.', 'The question "Ujumbe wa "Sungura na Fisi waliogawana mavuno" ni upi?" with "Sungura na Fisi waliogawana mavuno" among the options.', 'Close the text; say the lesson in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA.M8_FAS_MAINMINOR_T10', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA', 'Takes a minor character who appears often for the main character.', '{"question":"Mhusika mkuu katika \"Kilio cha Msitu\" ni nani?","wrong_answer":"Kazungu","correct_answer":"Bi. Zuhura"}'::jsonb, 'The child counts appearances, not who the story is about.', 'The question "Mhusika mkuu katika "Kilio cha Msitu" ni nani?" with "Kazungu" among the options.', 'Ask whose problem the story follows from start to end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA.M8_FAS_NOEVIDENCE_T10', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA', 'Gives a trait with no action from the text to show it.', '{"question":"Bi. Zuhura ni jasiri. Ni ushahidi upi unaothibitisha?","wrong_answer":"ni jasiri kwa sababu ni mhusika mzuri","correct_answer":"alisimama mbele ya malori ya mbao akakataa yapite"}'::jsonb, 'The child knows a trait must be named but not that it must be shown.', 'The question "Bi. Zuhura ni jasiri. Ni ushahidi upi unaothibitisha?" with "ni jasiri kwa sababu ni mhusika mzuri" among the options.', 'Use the frame: trait + "kwa sababu" + an action from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA.M8_FAS_LOOKS_T10', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA', 'Gives how the character looks (mrefu, mrembo) when the character''s nature is asked.', '{"question":"Taja sifa ya kitabia ya Bi. Zuhura.","wrong_answer":"mrefu na mwembamba","correct_answer":"jasiri"}'::jsonb, 'Describing people starts with appearance in lower grades.', 'The question "Taja sifa ya kitabia ya Bi. Zuhura." with "mrefu na mwembamba" among the options.', 'Two columns: sura (looks) and tabia (character); sort the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA.M8_FAS_LESSON_T10', 'KISW.G8.KUSOMA.T10_KUSOMA_KWA_KINA.TAMTHILIA_WAHUSIKA', 'Takes the behaviour of a bad character as the lesson to copy.', '{"question":"Tunajifunza nini kutokana na matendo ya Mzee Tamaa?","wrong_answer":"tufanye kama yeye ili tufanikiwe","correct_answer":"tuepuke tabia mbaya kama zake kwa sababu zina madhara"}'::jsonb, 'The bad character often wins for a while, and the child sees the gain, not the end.', 'The question "Tunajifunza nini kutokana na matendo ya Mzee Tamaa?" with "tufanye kama yeye ili tufanikiwe" among the options.', 'Follow the character to the end of the work: what did his actions bring?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA.M_KS8_BA_ANWANI', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA', 'Gives one address.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja","correct_answer":"mbili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "moja" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi ina anwani mbili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA.M_KS8_BA_KICHWA', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA', 'Leaves out the heading.', '{"question":"Barua rasmi huwa na nini kabla ya ujumbe?","wrong_answer":"hakuna kitu","correct_answer":"kichwa cha barua"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "hakuna kitu" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi ina kichwa cha barua.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA.M_KS8_BA_LUGHA', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA', 'Uses slang.', '{"question":"Lugha ya barua rasmi ni ipi?","wrong_answer":"ya mtaani","correct_answer":"ya heshima na sanifu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya mtaani" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi hutumia lugha ya heshima.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA.M8_INS_ONEADDR_T10', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA', 'Writes only one address, or puts the receiver''s address at the top right.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja, ya mwandishi","correct_answer":"mbili: ya mwandishi (kulia juu) na ya mpokeaji (kushoto)"}'::jsonb, 'The friendly letter has one address and the child carries it over.', 'The question "Barua rasmi ina anwani ngapi?" with "moja, ya mwandishi" among the options.', 'Label both addresses on a model; the child writes his own and the receiver''s on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA.M8_INS_NOREF_T10', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA', 'Leaves out the subject line (KUH: or YAH:) or writes it as a long sentence.', '{"question":"Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la msaada wa ushauri nasaha?","wrong_answer":"Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi.","correct_answer":"KUH: OMBI LA MSAADA WA USHAURI NASAHA"}'::jsonb, 'The child does not know the reader of an official letter needs the subject before reading.', 'The question "Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la msaada wa ushauri nasaha?" with "Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi." among the options.', 'Underline the KUH: line on three real letters; it is short and in capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA.M8_INS_CASUAL_T10', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA', 'Uses friendly words in an official letter (Mpendwa rafiki, Hujambo?, Wako akupendaye).', '{"question":"Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?","wrong_answer":"Hujambo mwalimu wangu mpendwa!","correct_answer":"Kwa Mwalimu Mkuu,"}'::jsonb, 'The friendly letter is the first letter learnt and its words come first.', 'The question "Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?" with "Hujambo mwalimu wangu mpendwa!" among the options.', 'Sort salamu and closing cards into "kirafiki" and "rasmi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA.M8_INS_SIGNOFF_T10', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAADA', 'Ends with only a first name and no signature, or with "Ni mimi rafiki yako".', '{"question":"Barua rasmi humalizika vipi?","wrong_answer":"Ni mimi rafiki yako, Wanjiku","correct_answer":"Wako mtiifu, sahihi, na jina kamili: Wanjiku Kamau"}'::jsonb, 'The friendly closing is a habit.', 'The question "Barua rasmi humalizika vipi?" with "Ni mimi rafiki yako, Wanjiku" among the options.', 'Model the closing block (Wako mtiifu, sahihi, jina kamili) and have the child copy it once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA.M8_BA_NOREQUEST', 'KISW.G8.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAADA', 'Describes the problem at length but never says clearly what help is asked for.', '{"question":"Ni sentensi ipi ni kiini cha barua ya kuomba msaada?","wrong_answer":"Nimekuwa na matatizo mengi nyumbani na shuleni.","correct_answer":"Naomba nipangiwe kikao na mshauri wa wanafunzi wiki hii."}'::jsonb, 'The child explains but is shy to ask.', 'The question "Ni sentensi ipi ni kiini cha barua ya kuomba msaada?" with "Nimekuwa na matatizo mengi nyumbani na shuleni." among the options.', 'Plan: the problem in brief, the exact request, why it would help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI.M_KS8_VT_KITENZI', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI', 'Gives a wrong verb antonym.', '{"question":"Kinyume cha fungua ni kipi?","wrong_answer":"nunua","correct_answer":"funga"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "nunua" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha fungua ni funga.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI.M_KS8_VT_KIELEZI', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI', 'Gives a wrong adverb antonym.', '{"question":"Kinyume cha polepole ni kipi?","wrong_answer":"chini","correct_answer":"haraka"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "chini" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha polepole ni haraka.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI.M_KS8_VT_NUNUA', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI', 'Gives a wrong antonym of nunua.', '{"question":"Kinyume cha nunua ni kipi?","wrong_answer":"pika","correct_answer":"uza"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pika" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha nunua ni uza.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI.M8_VT_NEGATE', 'KISW.G8.SARUFI.T10_VINYUME_VYA_VITENZI_.VINYUME_VITENZI', 'Gives the negative of the verb or adverb (hakununua, si haraka) as its opposite.', '{"question":"Kinyume cha \"haraka\" ni?","wrong_answer":"si haraka","correct_answer":"polepole"}'::jsonb, 'Negation feels like the opposite.', 'The question "Kinyume cha "haraka" ni?" with "si haraka" among the options.', 'An opposite is another word: haraka/polepole, nunua/uza, juu/chini.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO.M8_ORL_READOUT_T11', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO', 'Reads the notes word for word instead of speaking from them.', '{"question":"Vidokezo vya hoja hutumiwaje?","wrong_answer":"kusomwa neno kwa neno","correct_answer":"kukumbusha hoja huku ukizungumza na hadhira"}'::jsonb, 'Notes look like a script.', 'The question "Vidokezo vya hoja hutumiwaje?" with "kusomwa neno kwa neno" among the options.', 'Write only key words on the card; speak a sentence from each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO.M8_ORL_NOTEORDER_T11', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO', 'Speaks the points in random order, not the order of the notes.', '{"question":"Hoja zako zifuate mpangilio gani?","wrong_answer":"kama zinavyokujia","correct_answer":"mpangilio wa vidokezo ulivyoandaa"}'::jsonb, 'The child forgets the plan under pressure.', 'The question "Hoja zako zifuate mpangilio gani?" with "kama zinavyokujia" among the options.', 'Number the notes; tick each as it is spoken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO.M8_ORL_EYES_T11', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO.M8_ORL_OFFTOPIC_T11', 'KISW.G8.KUSIKI.T11_KUZUNGUMZA_KWA_KUTUM.VIDOKEZO', 'Answers or speaks on something other than the topic (haki ya mtoto kupata elimu).', '{"question":"Mada ni haki ya mtoto kupata elimu. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia haki ya mtoto kupata elimu kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni haki ya mtoto kupata elimu. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_COVER_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu haki za watoto. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu haki za watoto. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_LEVEL_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Sauti ya Mtoto\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Sauti ya Mtoto" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_TITLEMSG_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Sauti ya Mtoto\" ni upi?","wrong_answer":"Sauti ya Mtoto","correct_answer":"Kila mtoto ana haki ya elimu, ulinzi na kusikilizwa."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Sauti ya Mtoto" ni upi?" with "Sauti ya Mtoto" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_DETAIL_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu haki za watoto?","wrong_answer":"Amani alikuwa na miaka kumi na mbili.","correct_answer":"Kila mtoto ana haki ya elimu, ulinzi na kusikilizwa."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu haki za watoto?" with "Amani alikuwa na miaka kumi na mbili." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_KIND_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M8_MAP_WORD_T11', 'KISW.G8.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (dhuluma).', '{"question":"Katika matini: \"Dhuluma dhidi ya watoto lazima iripotiwe.\" Neno \"dhuluma\" lina maana gani?","wrong_answer":"zawadi ya siku ya kuzaliwa","correct_answer":"kunyimwa haki au kutendewa vibaya"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Dhuluma dhidi ya watoto lazima iripotiwe." Neno "dhuluma" lina maana gani?" with "zawadi ya siku ya kuzaliwa" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE.M8_INS_PARAS_T11', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Haki za Mtoto Shuleni\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Haki za Mtoto Shuleni" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE.M8_INS_MSAMIATI_T11', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Haki za Mtoto Shuleni\"?","wrong_answer":"Watoto wana haki nyingi.","correct_answer":"Kila mtoto ana haki ya kusoma katika mazingira salama bila kuadhibiwa kikatili."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Haki za Mtoto Shuleni"?" with "Watoto wana haki nyingi." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE.M8_INS_OFFTOPIC_T11', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Haki za Mtoto Shuleni\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kila mtoto ana haki ya kusoma katika mazingira salama bila kuadhibiwa kikatili."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Haki za Mtoto Shuleni", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE.M8_INS_STORY_T11', 'KISW.G8.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_VIPENGELE', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Haki za Mtoto Shuleni\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kila mtoto ana haki ya kusoma katika mazingira salama bila kuadhibiwa kikatili."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Haki za Mtoto Shuleni"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA.M_KS8_KT_TENDEKA', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA', 'Confuses kutendeka with kutendewa.', '{"question":"Ni kitenzi kipi kiko katika kauli ya kutendeka?","wrong_answer":"pikiwa","correct_answer":"pikika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pikiwa" next to the right answer and ask the question again in a new sentence.', 'Pikika ni kutendeka.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA.M_KS8_KT_TENDEWA', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA', 'Confuses kutendewa with kutendeka.', '{"question":"Ni kitenzi kipi kiko katika kauli ya kutendewa?","wrong_answer":"pikika","correct_answer":"pikiwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pikika" next to the right answer and ask the question again in a new sentence.', 'Pikiwa ni kutendewa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA.M_KS8_KT_TENDATENDA', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA', 'Does not know the repeated act.', '{"question":"Pigapiga humaanisha nini?","wrong_answer":"kupiga mara moja","correct_answer":"kupiga mara nyingi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kupiga mara moja" next to the right answer and ask the question again in a new sentence.', 'Pigapiga ni kupiga mara nyingi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA.M8_KT_TENDATENDA_FORM', 'KISW.G8.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDEKA', 'Repeats the whole word with its prefix (anapigapiga is right; the child writes anapiga-anapiga) or repeats a verb that does not take it.', '{"question":"Kauli ya kutendatenda ya \"anapiga\" ni?","wrong_answer":"anapiga anapiga","correct_answer":"anapigapiga"}'::jsonb, 'Repetition is heard as two words.', 'The question "Kauli ya kutendatenda ya "anapiga" ni?" with "anapiga anapiga" among the options.', 'Repeat the stem only, joined: piga -> pigapiga; the prefix once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI.M_KS8_LS_HABARI_DETAIL', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI.M_KS8_LS_HABARI_OPPOSITE', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI.M_KS8_LS_HABARI_NOTSAID', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI.M8_LSB_LS_HABARI', 'KISW.G8.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HABARI', 'Predicts what will happen without using what he heard.', '{"question":"Kutokana na habari uliyosikiliza, nini kitatokea?","wrong_answer":"chochote anachotaka","correct_answer":"jambo linalotokana na vidokezo vilivyosikika"}'::jsonb, 'Prediction is taken as wishing.', 'The question "Kutokana na habari uliyosikiliza, nini kitatokea?" with "chochote anachotaka" among the options.', 'Every prediction cites a clue heard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_WORDBYWORD_T12', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Kisukari na shinikizo la damu vinaweza kuzuiwa kwa lishe bora na mazoezi.\"?","wrong_answer":"Kisukari ... na ... shinikizo ... la ... damu ... vinaweza ... kuzuiwa ... kwa ... lishe ... bora ... na ... mazoezi.","correct_answer":"Kisukari na shinikizo la damu vinaweza kuzuiwa kwa lishe bora na mazoezi."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Kisukari na shinikizo la damu vinaweza kuzuiwa kwa lishe bora na mazoezi."?" with "Kisukari ... na ... shinikizo ... la ... damu ... vinaweza ... kuzuiwa ... kwa ... lishe ... bora ... na ... mazoezi." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_RACE_T12', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_FLAT_T12', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, unafanya mazoezi kila siku?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, unafanya mazoezi kila siku?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_NOPAUSE_T12', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Hongera, umepunguza sukari mwilini!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Hongera, umepunguza sukari mwilini!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M8_UFS_SOUND_T12', 'KISW.G8.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (mazoezi read as masoezi).', '{"question":"Neno \"mazoezi\" linatamkwa vipi?","wrong_answer":"masoezi","correct_answer":"mazoezi"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "mazoezi" linatamkwa vipi?" with "masoezi" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI.M8_INS_ITIFAKI_T12', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI', 'Starts the speech with no greeting of the guests in order (itifaki).', '{"question":"Hotuba huanza vipi?","wrong_answer":"moja kwa moja na hoja ya kwanza","correct_answer":"kwa itifaki: Mheshimiwa mgeni rasmi, walimu, wazazi..."}'::jsonb, 'The child writes a speech like an insha.', 'The question "Hotuba huanza vipi?" with "moja kwa moja na hoja ya kwanza" among the options.', 'Model the itifaki line and the order of rank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI.M8_INS_ESSAY_T12', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI', 'Writes about the listeners in the third person instead of speaking to them (Wanafunzi wanapaswa... instead of Wanafunzi wenzangu, tunapaswa...).', '{"question":"Ni sentensi ipi inafaa katika hotuba?","wrong_answer":"Wanafunzi wanapaswa kunawa mikono.","correct_answer":"Wanafunzi wenzangu, tunapaswa kunawa mikono."}'::jsonb, 'The speech is written, so it takes the voice of an essay.', 'The question "Ni sentensi ipi inafaa katika hotuba?" with "Wanafunzi wanapaswa kunawa mikono." among the options.', 'Read the draft aloud to the class; change every "wao" to "sisi" or "nyinyi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI.M8_INS_NOTHANKS_T12', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI', 'Ends without thanking the audience or closing (Asanteni kwa kunisikiliza).', '{"question":"Hotuba humalizika vipi?","wrong_answer":"kwa hoja ya mwisho tu","correct_answer":"kwa muhtasari na \"Asanteni kwa kunisikiliza\""}'::jsonb, 'The child stops when the points run out.', 'The question "Hotuba humalizika vipi?" with "kwa hoja ya mwisho tu" among the options.', 'Model a closing: a call to act and thanks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI.M8_INS_FACTLESS_T12', 'KISW.G8.KUANDI.T12_INSHA_ZA_KIUAMILIFU.HOTUBA_UFAFANUZI', 'Gives an information speech with no facts the listener can use (dates, places, steps).', '{"question":"Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu kisukari ni nini na tunajikingaje?","wrong_answer":"Ugonjwa huu ni mbaya sana.","correct_answer":"Chanjo itatolewa katika zahanati ya Ruaka kuanzia Jumatatu ijayo."}'::jsonb, 'The child gives feelings, not information.', 'The question "Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu kisukari ni nini na tunajikingaje?" with "Ugonjwa huu ni mbaya sana." among the options.', 'Check the speech against nani, nini, lini, wapi, vipi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO.M_KS8_SC_MAANA', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO', 'Thinks it has no subordinate clause.', '{"question":"Sentensi changamano ina nini?","wrong_answer":"kishazi kimoja tu","correct_answer":"kishazi huru na tegemezi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kishazi kimoja tu" next to the right answer and ask the question again in a new sentence.', 'Changamano ina kishazi huru na tegemezi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO.M_KS8_SC_TEGEMEZI', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO', 'Thinks a dependent clause stands alone.', '{"question":"Kishazi tegemezi hufanya nini?","wrong_answer":"kinajitegemea","correct_answer":"hakijitegemei"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kinajitegemea" next to the right answer and ask the question again in a new sentence.', 'Kishazi tegemezi hakijitegemei.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO.M_KS8_SC_SAHILI', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO', 'Takes a simple sentence as complex.', '{"question":"Ni sentensi ipi ni changamano?","wrong_answer":"Mtoto analia.","correct_answer":"Mtoto aliyeshinda alipewa zawadi."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mtoto analia." next to the right answer and ask the question again in a new sentence.', 'Changamano ina kishazi tegemezi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO.M8_SC_AMBATANO', 'KISW.G8.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_CHANGAMANO', 'Calls a sentence with "na" or "lakini" (ambatano) changamano, or a sentence with amba- or -po- ambatano.', '{"question":"\"Mtoto ambaye alianguka amepelekwa hospitali\" ni sentensi gani?","wrong_answer":"ambatano","correct_answer":"changamano"}'::jsonb, 'Both have more than one verb.', 'The question ""Mtoto ambaye alianguka amepelekwa hospitali" ni sentensi gani?" with "ambatano" among the options.', 'Ask: can each part stand alone? Two that can: ambatano. One that cannot (amba-, -po-, kwa sababu): changamano.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI.M8_FSI_MAIN_T13', 'KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI', 'Names a character who only appears once as the main one.', '{"question":"Mhusika mkuu katika hadithi hii ni nani?","wrong_answer":"mhusika aliyetajwa mara moja","correct_answer":"Mzee Busara"}'::jsonb, 'The child picks the most striking name.', 'The question "Mhusika mkuu katika hadithi hii ni nani?" with "mhusika aliyetajwa mara moja" among the options.', 'Ask whom the whole text is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI.M8_FSI_NOEVID_T13', 'KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI', 'Gives a trait with no line or action as evidence.', '{"question":"Mzee Busara ni mkarimu. Thibitisha.","wrong_answer":"kwa sababu ni mzuri","correct_answer":"aliwakaribisha wageni na kuwapikia chakula chao"}'::jsonb, 'Naming the trait feels like the answer.', 'The question "Mzee Busara ni mkarimu. Thibitisha." with "kwa sababu ni mzuri" among the options.', 'Frame: sifa + kwa sababu + action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI.M8_FSI_ANIMAL_T13', 'KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI', 'Takes an animal character literally, not as standing for people (Sungura is just a hare).', '{"question":"Katika hadithi, Mzee Busara anawakilisha nini?","wrong_answer":"mnyama wa porini tu","correct_answer":"watu wenye tabia kama zake katika jamii"}'::jsonb, 'Animal characters look like animal facts.', 'The question "Katika hadithi, Mzee Busara anawakilisha nini?" with "mnyama wa porini tu" among the options.', 'Ask which people in the community behave like this character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI.M8_FSI_LESSON_T13', 'KISW.G8.KUSIKI.T13_HADITHI.WAHUSIKA_HADITHI', 'Draws the wrong lesson from a character (copy the trickster because he won).', '{"question":"Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?","wrong_answer":"tuwe wajanja ili tushinde","correct_answer":"ujanja wa kudanganya huleta adhabu"}'::jsonb, 'The trick is remembered; the ending is not.', 'The question "Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?" with "tuwe wajanja ili tushinde" among the options.', 'Trace the character to the end: what did he gain and lose?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU.M8_FAS_SIMMET_T13', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU', 'Calls a comparison with kama a sitiari, or one without kama a tashbihi.', '{"question":"\"Mzee Tamaa ni chatu anayemeza msitu\" ni mbinu gani?","wrong_answer":"tashbihi","correct_answer":"sitiari"}'::jsonb, 'Both compare; the child has not fixed which one uses kama, mithili ya or kana kwamba.', 'The question ""Mzee Tamaa ni chatu anayemeza msitu" ni mbinu gani?" with "tashbihi" among the options.', 'Circle kama, mithili ya, kana kwamba: present means tashbihi; absent means sitiari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU.M8_FAS_NAMEONLY_T13', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU', 'Names the device but cannot say what it does in the work.', '{"question":"Mbinu ya sitiari katika \"Mzee Tamaa ni chatu anayemeza msitu\" ina umuhimu gani?","wrong_answer":"ni sitiari","correct_answer":"inaonyesha ulafi wake wa mali"}'::jsonb, 'Devices have been taught as labels to find.', 'The question "Mbinu ya sitiari katika "Mzee Tamaa ni chatu anayemeza msitu" ina umuhimu gani?" with "ni sitiari" among the options.', 'Always add "inasaidia..." after the label: picture, feeling, stress, humour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU.M8_FAS_LITERAL_T13', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU', 'Reads a figure of speech literally.', '{"question":"\"Mzee Tamaa ni chatu anayemeza msitu\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"inaonyesha ulafi wake wa mali"}'::jsonb, 'The child reads the words, not the picture.', 'The question ""Mzee Tamaa ni chatu anayemeza msitu" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what does the writer want us to see?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU.M8_FAS_TAKRIRI_T13', 'KISW.G8.KUSOMA.T13_KUSOMA_KWA_KINA_TAMT.TAMTHILIA_MBINU', 'Does not notice repetition (takriri) or rhetorical questions as devices.', '{"question":"\"Nitarudi, nitarudi, nitarudi!\" ni mbinu gani?","wrong_answer":"kosa la uchapishaji","correct_answer":"takriri: kurudia neno kusisitiza"}'::jsonb, 'Repetition looks like a mistake to a child taught not to repeat words.', 'The question ""Nitarudi, nitarudi, nitarudi!" ni mbinu gani?" with "kosa la uchapishaji" among the options.', 'Read the line aloud; what feeling does the repetition add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI.M8_INS_DETAIL_T13', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Soko la Kongowea Asubuhi\"?","wrong_answer":"Soko lilikuwa kubwa.","correct_answer":"Harufu ya maembe mabivu na samaki wabichi iliyajaza mabanda yaliyosongamana."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Soko la Kongowea Asubuhi"?" with "Soko lilikuwa kubwa." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI.M8_INS_LUGHA_T13', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Soko la Kongowea Asubuhi\"?","wrong_answer":"Soko lilikuwa kubwa.","correct_answer":"Harufu ya maembe mabivu na samaki wabichi iliyajaza mabanda yaliyosongamana."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Soko la Kongowea Asubuhi"?" with "Soko lilikuwa kubwa." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI.M8_INS_PARAS_T13', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Soko la Kongowea Asubuhi\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Soko la Kongowea Asubuhi" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI.M8_INS_MSAMIATI_T13', 'KISW.G8.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_MAHALI', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Soko la Kongowea Asubuhi\"?","wrong_answer":"Soko lilikuwa kubwa.","correct_answer":"Harufu ya maembe mabivu na samaki wabichi iliyajaza mabanda yaliyosongamana."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Soko la Kongowea Asubuhi"?" with "Soko lilikuwa kubwa." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU.M_KS8_UT_TIMILIFU', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU', 'Uses hakuku- for timilifu.', '{"question":"Kanusha: Amefika.","wrong_answer":"Hakufika","correct_answer":"Hajafika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hakufika" next to the right answer and ask the question again in a new sentence.', 'Timilifu hukanushwa kwa ha-ja-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU.M_KS8_UT_MAZOEA', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU', 'Does not drop hu-.', '{"question":"Kanusha: Hufika.","wrong_answer":"Hahufika","correct_answer":"Hafiki"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hahufika" next to the right answer and ask the question again in a new sentence.', 'Hali ya mazoea hukanushwa kwa hafiki.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU.M_KS8_UT_WINGI', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU', 'Wrong plural negation.', '{"question":"Kanusha: Wamefika.","wrong_answer":"Hawakufika","correct_answer":"Hawajafika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hawakufika" next to the right answer and ask the question again in a new sentence.', 'Wingi ni hawajafika.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU.M8_UT_HU_SI', 'KISW.G8.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI_TIMILIFU', 'Negates hu- with si (Si huenda) instead of the present negative (Haendi / Hawaendi).', '{"question":"Kanusha: \"Yeye huenda sokoni kila Jumamosi.\"","wrong_answer":"Yeye si huenda sokoni kila Jumamosi.","correct_answer":"Yeye haendi sokoni kila Jumamosi."}'::jsonb, 'Si is the easiest negative word and hu- has no person prefix to change.', 'The question "Kanusha: "Yeye huenda sokoni kila Jumamosi."" with "Yeye si huenda sokoni kila Jumamosi." among the options.', 'The negative of a habit uses the present negative: ha- + stem + -i.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI.M8_FSI_DEVICE_T14', 'KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI', 'Does not see a device of language (repetition, simile, sound words) or calls it a mistake.', '{"question":"\"Panzi aliimba \"tia tia tia\"\" ni kipengele gani cha lugha?","wrong_answer":"kosa la lugha","correct_answer":"tanakali za sauti"}'::jsonb, 'The child has been told not to repeat words or use sounds in writing.', 'The question ""Panzi aliimba "tia tia tia"" ni kipengele gani cha lugha?" with "kosa la lugha" among the options.', 'Read aloud; what does the device add for the listener?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI.M8_FSI_LITERAL_T14', 'KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI', 'Reads a figure of speech literally.', '{"question":"\"Panzi aliimba \"tia tia tia\"\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"huleta uhai na burudani"}'::jsonb, 'The child reads words, not pictures.', 'The question ""Panzi aliimba "tia tia tia"" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what is meant?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI.M8_FSI_USE_T14', 'KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI', 'Names a device but cannot say why it matters (it makes the text nice).', '{"question":"Kipengele cha tanakali za sauti kina umuhimu gani?","wrong_answer":"kinapamba tu","correct_answer":"huleta uhai na burudani"}'::jsonb, 'Devices are taught as labels.', 'The question "Kipengele cha tanakali za sauti kina umuhimu gani?" with "kinapamba tu" among the options.', 'Always add what it does: picture, rhythm, memory, stress, feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI.M8_FSI_AUDIENCE_T14', 'KISW.G8.KUSIKI.T14_HADITHI.LUGHA_HADITHI', 'Does not see the call-and-response or the audience''s part as part of the language.', '{"question":"Msikilizaji anaposema \"Tega!\" au kuitikia wimbo, hiyo ni nini?","wrong_answer":"kelele zisizo na maana","correct_answer":"ushirikishaji wa hadhira, sehemu ya utungo"}'::jsonb, 'Written texts have no audience part.', 'The question "Msikilizaji anaposema "Tega!" au kuitikia wimbo, hiyo ni nini?" with "kelele zisizo na maana" among the options.', 'Perform it in class with and without the response; what is lost?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS8_RS_MJADALA_DETAIL', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS8_RS_MJADALA_OPPOSITE', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS8_RS_MJADALA_NOTSAID', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M8_MJD_RS_MJADALA', 'KISW.G8.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Gives only one side of the debate when both views are asked.', '{"question":"Kifungu kina mitazamo ipi kuhusu suala hili?","wrong_answer":"mtazamo wa upande mmoja tu","correct_answer":"mitazamo ya pande zote mbili"}'::jsonb, 'The child agrees with one side and reads only it.', 'The question "Kifungu kina mitazamo ipi kuhusu suala hili?" with "mtazamo wa upande mmoja tu" among the options.', 'Two columns: wanaounga mkono / wanaopinga; fill both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO.M8_INS_NOVIFAA_T14', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO', 'Starts the steps without saying what is needed (vifaa) or what the instructions are for.', '{"question":"Maelekezo ya \"Jinsi ya Kuweka Akiba kwa Simu\" huanza na nini?","wrong_answer":"hatua ya kwanza moja kwa moja","correct_answer":"lengo la maelekezo na vifaa vinavyohitajika"}'::jsonb, 'The child goes straight to doing.', 'The question "Maelekezo ya "Jinsi ya Kuweka Akiba kwa Simu" huanza na nini?" with "hatua ya kwanza moja kwa moja" among the options.', 'Plan: lengo, vifaa, hatua, tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO.M8_INS_STORYFORM_T14', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO', 'Tells what he did in the past (Nilichukua..., nilikoroga...) instead of giving instructions (Chukua..., koroga...).', '{"question":"Ni sentensi ipi inafaa katika insha ya maelekezo?","wrong_answer":"Nilichukua sufuria nikaweka maji.","correct_answer":"Chukua sufuria na uweke maji."}'::jsonb, 'The child turns instructions into a story of his own day.', 'The question "Ni sentensi ipi inafaa katika insha ya maelekezo?" with "Nilichukua sufuria nikaweka maji." among the options.', 'Underline the verbs; change each to the command or -e form (chukua, weka; uchukue).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO.M8_INS_ORDER_M_T14', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO', 'Gives the steps in an order that cannot work, with no signal words.', '{"question":"Ni mpangilio upi unafaa katika \"Jinsi ya Kuweka Akiba kwa Simu\"?","wrong_answer":"kagua salio, hamisha kiasi kidogo kila wiki, weka namba ya siri, fungua huduma ya akiba","correct_answer":"fungua huduma ya akiba, weka namba ya siri, hamisha kiasi kidogo kila wiki, kagua salio"}'::jsonb, 'The child lists steps as he remembers them.', 'The question "Ni mpangilio upi unafaa katika "Jinsi ya Kuweka Akiba kwa Simu"?" with "kagua salio, hamisha kiasi kidogo kila wiki, weka namba ya siri, fungua huduma ya akiba" among the options.', 'Act out the steps; number them; add kwanza, kisha, baadaye, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO.M8_INS_NOWARN_T14', 'KISW.G8.KUANDI.T14_INSHA_ZA_MAELEKEZO.MAELEKEZO', 'Leaves out safety warnings where the task needs them.', '{"question":"Ni kipi kinakosekana katika maelekezo ya \"Jinsi ya Kuweka Akiba kwa Simu\"?","wrong_answer":"anwani","correct_answer":"tahadhari ya usalama"}'::jsonb, 'Warnings are not part of the steps, so they are forgotten.', 'The question "Ni kipi kinakosekana katika maelekezo ya "Jinsi ya Kuweka Akiba kwa Simu"?" with "anwani" among the options.', 'Ask at each step: what could go wrong? Write a tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO.M_KS8_UD_KIJIJI', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO', 'Gives the wrong small noun.', '{"question":"Kijiji ni nini?","wrong_answer":"mji mkubwa","correct_answer":"mji mdogo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mji mkubwa" next to the right answer and ask the question again in a new sentence.', 'Kijiji ni mji mdogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO.M_KS8_UD_KIJITI', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO', 'Gives the wrong small noun.', '{"question":"Kijiti ni nini?","wrong_answer":"mti mkubwa","correct_answer":"mti mdogo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mti mkubwa" next to the right answer and ask the question again in a new sentence.', 'Kijiti ni mti mdogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO.M_KS8_UD_KIAMBISHI', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO', 'Wrong prefix for udogo.', '{"question":"Ni kiambishi kipi cha udogo?","wrong_answer":"ji-","correct_answer":"ki-"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ji-" next to the right answer and ask the question again in a new sentence.', 'Udogo hutumia ki-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO.M8_UD_AGREE', 'KISW.G8.SARUFI.T14_UDOGO_WA_NOMINO.UDOGO', 'Gives the small form but keeps the agreement of the ordinary noun (kijiji kidogo is right; the child writes kitoto analia).', '{"question":"Jaza: Kitoto ___ (kinalia / analia).","wrong_answer":"analia","correct_answer":"kinalia"}'::jsonb, 'The child changes the noun and keeps the person agreement.', 'The question "Jaza: Kitoto ___ (kinalia / analia)." with "analia" among the options.', 'Small forms move to KI-VI: kitoto kinalia, vitoto vinalia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2.M8_ORL_NOPARAPHRASE_T15', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2', 'Does not show he has understood (no paraphrase or question) and moves to his own story.', '{"question":"Mwenzako anakueleza tatizo lake. Ni jibu lipi la usikilizaji husishi?","wrong_answer":"Hilo si kitu, mimi nilikuwa na tatizo kubwa zaidi...","correct_answer":"Kwa hiyo unasema unahisi upweke shuleni? Pole sana."}'::jsonb, 'The child wants to share his own story.', 'The question "Mwenzako anakueleza tatizo lake. Ni jibu lipi la usikilizaji husishi?" with "Hilo si kitu, mimi nilikuwa na tatizo kubwa zaidi..." among the options.', 'Practise "Kwa hiyo unasema..." before any reply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2.M8_ORL_JUDGE_T15', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2', 'Judges or advises at once instead of listening first.', '{"question":"Rafiki ana huzuni. Unaanza kwa?","wrong_answer":"Hupaswi kuhuzunika!","correct_answer":"Nieleze kilichotokea, nakusikiliza."}'::jsonb, 'Advice feels like help.', 'The question "Rafiki ana huzuni. Unaanza kwa?" with "Hupaswi kuhuzunika!" among the options.', 'Listen, reflect, then ask before advising.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2.M8_ORL_INTERRUPT_T15', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2.M8_ORL_EYES_T15', 'KISW.G8.KUSIKI.T15_USIKILIZAJI_HUSISHI.USIKILIZAJI_HUSISHI_2', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS8_UF_NAKALA', 'KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Thinks a summary copies.', '{"question":"Ufupisho ni nini?","wrong_answer":"kunakili habari yote","correct_answer":"kutoa habari kuu kwa ufupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kunakili habari yote" next to the right answer and ask the question again in a new sentence.', 'Ufupisho ni habari kuu kwa ufupi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS8_UF_MAANA', 'KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Thinks meaning may change.', '{"question":"Ufupisho unapaswa kuwa vipi?","wrong_answer":"upoteze maana","correct_answer":"uhifadhi maana"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "upoteze maana" next to the right answer and ask the question again in a new sentence.', 'Ufupisho huhifadhi maana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS8_UF_KUU', 'KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Picks a detail as the main idea.', '{"question":"Habari kuu ya aya ni ipi?","wrong_answer":"mfano mdogo","correct_answer":"wazo kuu la aya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mfano mdogo" next to the right answer and ask the question again in a new sentence.', 'Habari kuu ni wazo kuu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M_KS8_RS_UFUPISHO_DETAIL', 'KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M_KS8_RS_UFUPISHO_OPPOSITE', 'KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M_KS8_RS_UFUPISHO_NOTSAID', 'KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M8_UFU_RS_UFUPISHO', 'KISW.G8.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Keeps the examples and numbers in the summary and leaves out a main point.', '{"question":"Ni lipi liingie katika ufupisho wa kifungu?","wrong_answer":"mfano mmoja wa kifungu","correct_answer":"hoja kuu ya kila aya"}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho wa kifungu?" with "mfano mmoja wa kifungu" among the options.', 'Underline the main point of each paragraph; cross out examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO.M8_UFU_UFUPISHO', 'KISW.G8.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Keeps the examples and numbers in the summary and leaves out a main point.', '{"question":"Ni lipi liingie katika ufupisho wa kifungu?","wrong_answer":"mfano mmoja wa kifungu","correct_answer":"hoja kuu ya kila aya"}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho wa kifungu?" with "mfano mmoja wa kifungu" among the options.', 'Underline the main point of each paragraph; cross out examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE.M_KS8_BP_MADA', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE', 'Leaves out the subject line.', '{"question":"Ni sehemu ipi ya baruapepe inaonyesha kichwa cha habari?","wrong_answer":"jina la mwandishi","correct_answer":"mada"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jina la mwandishi" next to the right answer and ask the question again in a new sentence.', 'Mada ni kichwa cha baruapepe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE.M_KS8_BP_LUGHA', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE', 'Uses slang in an office email.', '{"question":"Lugha ya baruapepe ya kiofisi ni ipi?","wrong_answer":"ya mtaani","correct_answer":"rasmi na fupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya mtaani" next to the right answer and ask the question again in a new sentence.', 'Baruapepe ya kiofisi ni rasmi na fupi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE.M_KS8_BP_ANWANI', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE', 'Uses the wrong address field.', '{"question":"Anwani ya mpokeaji huandikwa wapi?","wrong_answer":"mwishoni","correct_answer":"sehemu ya \"Kwa\""}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mwishoni" next to the right answer and ask the question again in a new sentence.', 'Mpokeaji huandikwa kwenye "Kwa".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI.M8_INS_NOSUBJ_T15', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI', 'Leaves the subject box empty or writes the whole message in it.', '{"question":"Katika baruapepe, kisanduku cha \"Kichwa\" kinaandikwa nini?","wrong_answer":"ujumbe wote","correct_answer":"maneno machache yanayotaja ujumbe, kama \"Ombi la Kushiriki Kongamano la Maadili\""}'::jsonb, 'The child has used chat apps that have no subject line.', 'The question "Katika baruapepe, kisanduku cha "Kichwa" kinaandikwa nini?" with "ujumbe wote" among the options.', 'Show an inbox: the subject is all the reader sees before opening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI.M8_INS_ADDR_T15', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI', 'Writes a postal address and a date at the top, as in a paper letter.', '{"question":"Baruapepe huanza vipi?","wrong_answer":"S.L.P. 120, Nakuru, na tarehe juu kulia","correct_answer":"salamu kwa mpokeaji, kama \"Habari Amina,\""}'::jsonb, 'The paper letter is the model the child knows.', 'The question "Baruapepe huanza vipi?" with "S.L.P. 120, Nakuru, na tarehe juu kulia" among the options.', 'Compare a paper letter and an email; the email programme adds the address and date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI.M8_INS_TOFIELD_T15', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI', 'Puts the receiver''s name, not the email address, in the "Kwa" box.', '{"question":"Kisanduku cha \"Kwa\" kinaandikwa nini?","wrong_answer":"Amina Otieno","correct_answer":"amina.otieno@mfano.co.ke"}'::jsonb, 'The child writes the person as on an envelope.', 'The question "Kisanduku cha "Kwa" kinaandikwa nini?" with "Amina Otieno" among the options.', 'Show what an email address looks like (jina@mahali); practise reading it aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI.M8_INS_TEXTSPEAK_T15', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.KUANDIKA_BARUAPEPE_KIOFISI', 'Writes in short chat forms (sawa, poa, nkt, 2moro) and no closing.', '{"question":"Ni sentensi ipi inafaa katika baruapepe?","wrong_answer":"Poa, tutaonana 2moro.","correct_answer":"Asante. Tutaonana kesho."}'::jsonb, 'Chat habits come into the email.', 'The question "Ni sentensi ipi inafaa katika baruapepe?" with "Poa, tutaonana 2moro." among the options.', 'Rewrite one chat message as a short email with a greeting and a closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE.M8_BP_CC', 'KISW.G8.KUANDI.T15_BARUAPEPE_YA_KIOFISI.BARUAPEPE', 'Puts everyone in the "Kwa" box, or sends an office email to the wrong person, not using "Nakala kwa" (cc).', '{"question":"Unamtumia mratibu baruapepe na unataka mwalimu wako aone pia. Mwalimu awekwe wapi?","wrong_answer":"katika kisanduku cha \"Kwa\" pamoja na mratibu","correct_answer":"katika kisanduku cha \"Nakala kwa\" (cc)"}'::jsonb, 'The child has only used the "Kwa" box.', 'The question "Unamtumia mratibu baruapepe na unataka mwalimu wako aone pia. Mwalimu awekwe wapi?" with "katika kisanduku cha "Kwa" pamoja na mratibu" among the options.', 'Show the boxes: Kwa (who must act), Nakala kwa (who should know).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA.M_KS8_UTA_ALAMA', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA', 'Keeps quotation marks.', '{"question":"Ni usemi upi ni wa taarifa?","wrong_answer":"Baba alisema, \"Nimechoka.\"","correct_answer":"Baba alisema kwamba amechoka."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Baba alisema, "Nimechoka."" next to the right answer and ask the question again in a new sentence.', 'Usemi wa taarifa hauna alama za usemi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA.M_KS8_UTA_HALISI', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA', 'Mixes halisi with taarifa.', '{"question":"Ni usemi upi ni halisi?","wrong_answer":"Baba alisema kwamba amechoka.","correct_answer":"Baba alisema, \"Nimechoka.\""}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Baba alisema kwamba amechoka." next to the right answer and ask the question again in a new sentence.', 'Usemi halisi una alama za usemi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA.M_KS8_UTA_MTU', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA', 'Keeps the person the same.', '{"question":"Juma alisema, \"Mimi ni mgonjwa.\" Taarifa ni ipi?","wrong_answer":"Juma alisema kwamba mimi ni mgonjwa.","correct_answer":"Juma alisema kwamba yeye ni mgonjwa."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Juma alisema kwamba mimi ni mgonjwa." next to the right answer and ask the question again in a new sentence.', 'Mtu hubadilika: mimi huwa yeye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA.M8_UTA_QUESTION', 'KISW.G8.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_TAARIFA', 'Keeps the question form and the question mark when reporting a question (Aliuliza kwamba utakuja?).', '{"question":"Badilisha: Mama aliuliza, \"Utakuja lini?\"","wrong_answer":"Mama aliuliza kwamba utakuja lini?","correct_answer":"Mama aliuliza ningekuja lini."}'::jsonb, 'The child changes the frame but keeps the question as it was.', 'The question "Badilisha: Mama aliuliza, "Utakuja lini?"" with "Mama aliuliza kwamba utakuja lini?" among the options.', 'Reported questions end with a full stop, change the person and tense, and drop kwamba before a question word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
